#[allow(unused_macro_rules)]
macro_rules! routing_test {
    (sync $name:ident $($body:tt)*) => {
        #[test]
        fn $name() { $($body)* }
    };
    (async $name:ident $($body:tt)*) => {
        #[tokio::test]
        async fn $name() { $($body)* }
    };
    (current_thread $name:ident $($body:tt)*) => {
        #[tokio::test(flavor = "current_thread")]
        async fn $name() { $($body)* }
    };
}

macro_rules! app_api_items {
    ($($item:item)*) => {
        $(#[cfg(feature = "app_api")] $item)*
    };
}

macro_rules! derived_items {
    ($($(#[$attribute:meta])* ($($derive:path),+ $(,)?) $item:item)*) => {
        $($(#[$attribute])* #[derive($($derive),+)] $item)*
    };
}

