#[derive(Debug, crate::json_macros::JsonDeserialize, norito::derive::NoritoDeserialize)]
/// Query parameters for WebSocket Connect endpoint
pub struct ConnectWsQuery {
    /// Session identifier (base64url, no padding)
    pub sid: String,
    /// Role name: "app" or "wallet"
    pub role: String,
}
#[cfg(all(test, feature = "connect"))]
mod connect_session_tests {
    use super::*;
    use base64::engine::general_purpose::URL_SAFE_NO_PAD as B64;
    use iroha_crypto::{Hash, HashOf};
    use iroha_data_model::{NetworkId, block::BlockHeader};
    use rand::rand_core::{TryCryptoRng, TryRngCore};
    struct FailingConnectSessionRng;
    #[derive(Debug)]
    struct FailingConnectSessionRngError;
    impl std::fmt::Display for FailingConnectSessionRngError {
        fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
            f.write_str("failing Connect session RNG")
        }
    }
    impl TryRngCore for FailingConnectSessionRng {
        type Error = FailingConnectSessionRngError;
        fn try_next_u32(&mut self) -> Result<u32, Self::Error> {
            Err(FailingConnectSessionRngError)
        }
        fn try_next_u64(&mut self) -> Result<u64, Self::Error> {
            Err(FailingConnectSessionRngError)
        }
        fn try_fill_bytes(&mut self, _dst: &mut [u8]) -> Result<(), Self::Error> {
            Err(FailingConnectSessionRngError)
        }
    }
    impl TryCryptoRng for FailingConnectSessionRng {}
    fn network_id(label: &[u8]) -> NetworkId {
        NetworkId::from_genesis_hash(HashOf::<BlockHeader>::from_untyped_unchecked(Hash::new(
            label,
        )))
    }
    fn valid_request(network_id: NetworkId) -> ConnectSessionRequest {
        let app_pk = [0x33; 32];
        let nonce = [0x44; 16];
        let sid = iroha_torii_shared::connect_sdk::derive_session_id(&network_id, &app_pk, &nonce);
        ConnectSessionRequest {
            sid: B64.encode(sid),
            network_id,
            app_pk: B64.encode(app_pk),
            nonce: B64.encode(nonce),
            node: None,
        }
    }
    routing_test! { async connect_session_requires_client_sid
        let network_id = network_id(b"connect-session-genesis");
        let mut req = valid_request(network_id);
        req.sid.clear();
        let err = handle_connect_session(network_id, NoritoJson(req))
            .await
            .err();
        assert!(err.is_some(), "expected error when sid is missing");
    }
    routing_test! { async connect_session_accepts_valid_sid_b64
        let network_id = network_id(b"connect-session-genesis");
        let req = valid_request(network_id);
        let sid_str = req.sid.clone();
        let app_pk = req.app_pk.clone();
        let nonce = req.nonce.clone();
        let resp = handle_connect_session(network_id, NoritoJson(req))
            .await
            .expect("ok");
        assert_eq!(resp.0.sid, sid_str);
        assert_eq!(resp.0.network_id, network_id);
        assert_eq!(resp.0.app_pk, app_pk);
        assert_eq!(resp.0.nonce, nonce);
        assert!(
            resp.0.token_app.len() > 0
                && resp.0.token_wallet.len() > 0
                && resp.0.token_management.len() > 0
                && resp.0.token_relay.len() > 0
        );
        assert!(resp.0.wallet_uri.contains(&sid_str));
        assert!(resp.0.app_uri.contains(&sid_str));
        assert!(resp.0.wallet_uri.contains("&relay="));
        assert!(resp.0.app_uri.contains("&relay="));
        const CANONICAL_NETWORK_ID: &str =
            "hash:445E0F6E4B393BFB5FA7688DA17D509A9B4F8DFC9032DE25C65C83DD7C7FBF7D#6120";
        for uri in [&resp.0.wallet_uri, &resp.0.app_uri] {
            let parsed = url::Url::parse(uri).expect("valid Connect URI");
            let network_ids = parsed
                .query_pairs()
                .filter_map(|(key, value)| (key == "network_id").then(|| value.into_owned()))
                .collect::<Vec<_>>();
            assert_eq!(network_ids, vec![CANONICAL_NETWORK_ID.to_owned()]);
            assert!(!parsed.query_pairs().any(|(key, _)| key == "chain_id"));
        }
    }
    routing_test! { async connect_session_rejects_hex_sid
        let network_id = network_id(b"connect-session-genesis");
        let mut req = valid_request(network_id);
        req.sid = hex::encode([9u8; 32]);
        let err = handle_connect_session(network_id, NoritoJson(req))
            .await
            .err();
        assert!(err.is_some(), "expected error when sid is hex");
    }
    routing_test! { async connect_session_rejects_same_label_different_genesis_before_rng
        let expected = network_id(b"same-display-label-genesis-a");
        let supplied = network_id(b"same-display-label-genesis-b");
        let req = valid_request(supplied);
        let err = handle_connect_session_with_rng(expected, req, &mut FailingConnectSessionRng)
            .await
            .err()
            .expect("wrong exact network must fail before token generation");
        assert!(matches!(
            err,
            crate::Error::Query(iroha_data_model::ValidationFail::QueryFailed(_))
        ));
    }
    routing_test! { async connect_session_rejects_sid_network_substitution
        let expected = network_id(b"connect-session-genesis-a");
        let other = network_id(b"connect-session-genesis-b");
        let mut req = valid_request(expected);
        req.sid = valid_request(other).sid;
        let err = handle_connect_session(expected, NoritoJson(req))
            .await
            .err();
        assert!(err.is_some(), "SID from another network must be rejected");
    }
    routing_test! { async connect_session_reports_token_rng_failure
        let network_id = network_id(b"connect-session-genesis");
        let req = valid_request(network_id);
        let err =
            match handle_connect_session_with_rng(network_id, req, &mut FailingConnectSessionRng)
                .await
            {
                Ok(_) => panic!("Connect session token RNG failure must be reported"),
                Err(err) => err,
            };
        match err {
            crate::Error::Query(iroha_data_model::ValidationFail::InternalError(message)) => {
                assert!(message.contains("Connect session app token"));
                assert!(message.contains("failing Connect session RNG"));
            }
            other => panic!("expected Connect session RNG internal error, got {other:?}"),
        }
    }
    include!("routing/connect_session_request_decode_tests.rs");
}
