#[cfg(test)]
fn bind_account_alias_for_test(
    state: &std::sync::Arc<iroha_core::state::State>,
    account_id: &AccountId,
    alias_literal: &str,
) {
    use iroha_core::smartcontracts::Execute as _;
    let catalog = state.nexus_snapshot().dataspace_catalog;
    let label =
        iroha_data_model::account::rekey::AccountAlias::from_literal(alias_literal, &catalog)
            .expect("valid account alias");
    let selector = iroha_core::sns::selector_for_account_alias(&label, &catalog)
        .expect("account alias selector");
    let address = iroha_data_model::account::AccountAddress::from_account_id(account_id)
        .expect("account alias owner address");
    let record = iroha_data_model::sns::NameRecordV1::new(
        selector.clone(),
        account_id.clone(),
        vec![iroha_data_model::sns::NameControllerV1::account(&address)],
        0,
        0,
        u64::MAX,
        u64::MAX,
        u64::MAX,
        iroha_model_base::metadata::Metadata::default(),
    );
    let header =
        iroha_data_model::block::BlockHeader::new(nonzero_ext::nonzero!(1_u64), None, None, 0, 0);
    let mut block = state.block(header);
    let mut tx = block.transaction();
    // Alias repair validates the parent namespace before the existing child lease.
    // These fixtures register universal accounts first and seed the independently
    // owned parent lease explicitly instead of relying on catalog membership.
    let resolved_alias = iroha_data_model::alias_setup::ResolvedAccountAliasV1::resolve_catalog(
        alias_literal,
        &catalog,
    )
    .expect("resolved account alias");
    let parent_selector = if let Some(domain) = resolved_alias.parent_domain() {
        iroha_core::sns::selector_for_domain(&domain.canonical_name)
    } else {
        iroha_core::sns::selector_for_dataspace_alias(
            resolved_alias.canonical_name.dataspace.as_ref(),
        )
    }
    .expect("account alias parent selector");
    let mut parent_metadata = iroha_model_base::metadata::Metadata::default();
    if resolved_alias.parent_domain().is_none() {
        parent_metadata.insert(
            iroha_core::sns::SNS_DATASPACE_ID_METADATA_KEY
                .parse()
                .expect("dataspace metadata key"),
            iroha_primitives::json::Json::new(label.dataspace.as_u64()),
        );
    }
    let parent_record = iroha_data_model::sns::NameRecordV1::new(
        parent_selector.clone(),
        account_id.clone(),
        vec![iroha_data_model::sns::NameControllerV1::account(&address)],
        0,
        0,
        u64::MAX,
        u64::MAX,
        u64::MAX,
        parent_metadata,
    );
    tx.world_mut_for_testing()
        .smart_contract_state_mut_for_testing()
        .insert(
            iroha_core::sns::record_storage_key(&parent_selector),
            norito::codec::Encode::encode(&parent_record),
        );
    tx.world_mut_for_testing()
        .smart_contract_state_mut_for_testing()
        .insert(
            iroha_core::sns::record_storage_key(&selector),
            norito::codec::Encode::encode(&record),
        );
    iroha_data_model::isi::alias_setup::EnsureAlias::new(
        iroha_data_model::alias_setup::AliasIntentV1::AccountAlias(
            iroha_data_model::alias_setup::AliasAccountIntentV1 {
                alias: resolved_alias,
                target_account: account_id.clone(),
                provision: iroha_data_model::alias_setup::AccountProvisionV1::Existing,
                role: iroha_data_model::alias_setup::AccountAliasRoleV1::Additional,
            },
        ),
        iroha_data_model::alias_setup::AliasLeaseAcquisitionV1::new(1, None),
        iroha_data_model::alias_setup::AliasQuoteGuardV1 {
            expected_policy_version: 0,
            expected_payment_asset:
                iroha_data_model::asset::AssetDefinitionId::derive_from_components(
                    iroha_model_base::domain::DomainId::try_new("assets", "universal")
                        .expect("fixture asset domain"),
                    "xor".parse().expect("fixture asset name"),
                ),
            max_amount: iroha_primitives::numeric::Quantity::zero(),
            valid_until_ms: 0,
        },
    )
    .execute(account_id, &mut tx)
    .expect("repair account alias binding from active SNS lease");
    tx.apply();
    block
        .commit_world_overlay_for_testing()
        .expect("commit account alias for test");
    let state_view = state.view();
    assert_eq!(
        iroha_core::sns::active_account_alias_owner(state_view.world(), &catalog, &label, 0,)
            .expect("valid active account-alias owner state")
            .as_ref(),
        Some(account_id),
        "active SNS account-alias lease must resolve to the fixture account",
    );
    assert_eq!(
        iroha_core::sns::resolve_active_account_alias(state_view.world(), &catalog, &label, 0,)
            .expect("valid account-alias resolution state")
            .as_ref(),
        Some(account_id),
        "authoritative account-alias lease and binding indexes must agree",
    );
}
#[cfg(test)]
fn bind_universal_account_alias_on_world_for_test(
    world: &iroha_core::state::World,
    account_id: &AccountId,
    alias_literal: &str,
) {
    let catalog = iroha_data_model::nexus::DataSpaceCatalog::default();
    let label =
        iroha_data_model::account::rekey::AccountAlias::from_literal(alias_literal, &catalog)
            .expect("valid universal account alias");
    let selector = iroha_core::sns::selector_for_account_alias(&label, &catalog)
        .expect("account alias selector");
    let mut block = world.block();
    let mut tx = block
        .transaction_without_telemetry(iroha_config::parameters::actual::LaneConfig::default(), 0);
    insert_account_alias_binding_for_test(&mut tx, account_id, label.clone(), &catalog);
    tx.apply();
    block.commit();
    let world_view = world.view();
    assert_eq!(
        iroha_core::sns::active_owner_by_selector(&world_view, &selector, 0)
            .expect("valid active owner state")
            .as_ref(),
        Some(account_id),
        "active SNS account-alias record must be committed to fixture state",
    );
    assert_eq!(
        iroha_core::sns::active_account_alias_selector(&world_view, &catalog, &label, 0)
            .expect("active account-alias selector"),
        selector,
        "active and statically rendered account-alias selectors must agree",
    );
    assert_eq!(
        iroha_core::sns::active_account_alias_owner(&world_view, &catalog, &label, 0)
            .expect("valid active account-alias owner state")
            .as_ref(),
        Some(account_id),
        "active SNS account-alias lease must resolve to the fixture account",
    );
    assert_eq!(
        iroha_core::sns::resolve_active_account_alias(&world_view, &catalog, &label, 0)
            .expect("valid account-alias resolution state")
            .as_ref(),
        Some(account_id),
        "authoritative account-alias lease and binding indexes must agree",
    );
}
#[cfg(test)]
fn grant_account_alias_resolve_for_test(
    state: &std::sync::Arc<iroha_core::state::State>,
    authority: &AccountId,
    alias_literal: &str,
) {
    use iroha_core::smartcontracts::Execute as _;
    let catalog = &state.nexus_snapshot().dataspace_catalog;
    let alias =
        iroha_data_model::account::rekey::AccountAlias::from_literal(alias_literal, catalog)
            .expect("valid account alias");
    let scope = match alias.domain_id(catalog).expect("valid alias domain") {
        Some(domain_id) => {
            iroha_executor_data_model::permission::account::AccountAliasPermissionScope::Domain(
                domain_id,
            )
        }
        None => {
            iroha_executor_data_model::permission::account::AccountAliasPermissionScope::Dataspace(
                alias.dataspace,
            )
        }
    };
    let permission: iroha_data_model::permission::Permission =
        iroha_executor_data_model::permission::account::CanResolveAccountAlias { scope }.into();
    let header =
        iroha_data_model::block::BlockHeader::new(nonzero_ext::nonzero!(1_u64), None, None, 0, 0);
    let mut block = state.block(header);
    let mut tx = block.transaction();
    iroha_data_model::isi::Grant::account_permission(permission, authority.clone())
        .execute(authority, &mut tx)
        .expect("grant account-alias resolve permission");
    tx.apply();
    block
        .commit_world_overlay_for_testing()
        .expect("commit account-alias resolve permission");
}
/// Exercise the real executor alias-permission boundary before a public canonical-ID read.
#[cfg(all(test, feature = "app_api"))]
pub(crate) fn resolve_account_alias_with_exact_permission_for_test(
    state: &Arc<CoreState>,
    authority: &AccountId,
    alias_literal: &str,
) -> AccountId {
    use iroha_core::{
        query::snapshot::{SnapshotQueryError, run_on_snapshot},
        smartcontracts::isi::query::QueryLimits,
    };
    use iroha_data_model::query::{QueryRequest, QueryResponse, SingularQueryOutputBox};
    let catalog = state.nexus_snapshot().dataspace_catalog;
    let alias = account::rekey::AccountAlias::from_literal(alias_literal, &catalog)
        .expect("canonical fixture alias");
    let request = || {
        QueryRequest::Singular(
            iroha_data_model::query::account::prelude::FindAccountByAlias::new(alias.clone())
                .into(),
        )
    };
    let store = iroha_core::query::store::LiveQueryStore::start_test();
    let denied = run_on_snapshot(state, &store, authority, request(), QueryLimits::default())
        .expect_err("registered identity must not substitute for exact alias permission");
    assert!(
        matches!(
            denied,
            SnapshotQueryError::Validation(ValidationFail::NotPermitted(_))
        ),
        "original alias permission refusal: {denied:?}"
    );
    // The alias owner keeps its provisioned exact grant. An independent resolver
    // receives only the same alias scope, without widening to its domain or dataspace.
    let scope = iroha_executor_data_model::permission::account::AccountAliasPermissionScope::Alias(
        iroha_data_model::alias_setup::ResolvedAccountAliasV1::resolve_catalog(
            alias_literal,
            &catalog,
        )
        .expect("canonical exact alias grant"),
    );
    let permission: iroha_data_model::permission::Permission =
        iroha_executor_data_model::permission::account::CanResolveAccountAlias { scope }.into();
    let header =
        iroha_data_model::block::BlockHeader::new(nonzero_ext::nonzero!(1_u64), None, None, 0, 0);
    let mut block = state.block(header);
    let mut tx = block.transaction();
    iroha_core::smartcontracts::Execute::execute(
        iroha_data_model::isi::Grant::account_permission(permission, authority.clone()),
        authority,
        &mut tx,
    )
    .expect("grant original exact alias permission to independent resolver");
    tx.apply();
    block
        .commit_world_overlay_for_testing()
        .expect("commit exact alias permission");
    let resolved = run_on_snapshot(state, &store, authority, request(), QueryLimits::default())
        .expect("exact alias grant must authorize original executor resolution");
    let QueryResponse::Singular(SingularQueryOutputBox::Account(account)) = resolved else {
        panic!("alias query must return its original account");
    };
    account.id().clone()
}
