/// POST /v1/contracts/call/multisig/propose — propose a multisig participation envelope
/// for a contract call.
#[iroha_futures::telemetry_future]
pub async fn handle_post_contract_call_multisig_propose(
    queue: Arc<Queue>,
    state: Arc<CoreState>,
    telemetry: MaybeTelemetry,
    NoritoJson(req): NoritoJson<MultisigContractCallProposeDto>,
) -> Result<Response> {
    use iroha_data_model::prelude as dm;
    use iroha_executor_data_model::isi::multisig::{MultisigApprove, MultisigPropose};
    let MultisigContractCallProposeDto {
        selector,
        signer_account_id,
        public_key_hex,
        signature_b64,
        creation_time_ms,
        contract_alias,
        entrypoint,
        payload,
        fee_payment,
    } = req;
    validate_app_api_fee_payment(&fee_payment, true)?;
    let selector_alias_literal = selected_multisig_alias_literal(&selector);
    reject_unverified_multisig_alias_selector(&selector)?;
    let (multisig_account_id, spec) =
        resolve_multisig_account_and_spec(&state, &selector, Some(&signer_account_id))?;
    if !spec.signatories.contains_key(&signer_account_id) {
        iroha_logger::warn!(
            selector_alias = ?selector_alias_literal,
            resolved_multisig_account_id = %multisig_account_id,
            signer_account_id = %signer_account_id,
            "multisig contract-call propose rejected: signer is not present in live spec"
        );
        return Err(multisig_selector_conflict_error(
            "multisig_signer_not_in_spec",
            format!(
                "signer `{signer_account_id}` is not present in the resolved live multisig spec for `{multisig_account_id}`"
            ),
        ));
    }
    let prepared = resolve_contract_call_target(&state, None, Some(&contract_alias))?;
    let PreparedContractCall {
        program,
        code_hash,
        abi_hash: _,
        manifest,
        dataspace: _dataspace,
        contract_address,
        contract_alias,
    } = prepared;
    let entrypoint_descriptor = ensure_callable_contract_entrypoint(&manifest, &entrypoint)?;
    let normalized_payload = normalize_contract_payload(entrypoint_descriptor, Some(&payload))?;
    if !normalized_payload
        .as_ref()
        .cloned()
        .and_then(|value| value.try_into_any_norito::<Value>().ok())
        .is_some_and(|value| value.as_object().is_some())
    {
        return Err(multisig_selector_conflict_error(
            "multisig_contract_object_payload_required",
            "contract multisig proposals require an exact object payload",
        ));
    }
    let mint_request_alias: iroha_data_model::smart_contract::ContractAlias =
        "apps_mint_request::cbsi"
            .parse()
            .expect("static CBSI mint-request contract alias");
    let targets_mint_request = contract_alias.as_ref() == Some(&mint_request_alias) || {
        let world = state.world_view();
        world.contract_aliases().get(&mint_request_alias) == Some(&contract_address)
    };
    if targets_mint_request {
        if contract_alias.as_ref() != Some(&mint_request_alias) {
            return Err(multisig_selector_conflict_error(
                "mint_request_alias_required",
                "CBSI mint requests must target the canonical contract alias",
            ));
        }
        let payload_value = normalized_payload
            .as_ref()
            .cloned()
            .and_then(|value| value.try_into_any_norito::<Value>().ok())
            .ok_or_else(|| {
                multisig_selector_conflict_error(
                    "mint_request_payload_invalid",
                    "CBSI mint requests require an exact object payload",
                )
            })?;
        let payload_object = payload_value.as_object().ok_or_else(|| {
            multisig_selector_conflict_error(
                "mint_request_payload_invalid",
                "CBSI mint requests require an exact object payload",
            )
        })?;
        match entrypoint.as_str() {
            "create_mint_request" => {
                let creation_alias = payload_object
                    .get("creation_multisig_alias_fqn")
                    .and_then(Value::as_str)
                    .ok_or_else(|| {
                        multisig_selector_conflict_error(
                            "mint_request_creation_alias_invalid",
                            "mint request creation requires a canonical creation multisig alias",
                        )
                    })?;
                let creation_account =
                    resolve_exact_active_account_alias(state.as_ref(), creation_alias)?;
                if creation_account != multisig_account_id {
                    return Err(multisig_selector_conflict_error(
                        "mint_request_creation_authority_mismatch",
                        "the creation alias must resolve to the exact proposal multisig authority",
                    ));
                }
                let approval_account =
                    resolve_exact_active_account_alias(state.as_ref(), "banking@cbsi")?;
                if approval_account == multisig_account_id {
                    return Err(multisig_selector_conflict_error(
                        "mint_request_principals_not_distinct",
                        "the creation and CBSI approval multisig authorities must be distinct",
                    ));
                }
                load_multisig_spec(state.as_ref(), &approval_account)?;
            }
            "finalize_mint_request" => {
                let approval_account =
                    resolve_exact_active_account_alias(state.as_ref(), "banking@cbsi")?;
                if approval_account != multisig_account_id {
                    return Err(multisig_selector_conflict_error(
                        "mint_request_approval_authority_mismatch",
                        "mint request finalization requires the live banking@cbsi multisig authority",
                    ));
                }
            }
            "cancel_mint_request" => {}
            _ => {
                return Err(multisig_selector_conflict_error(
                    "mint_request_entrypoint_invalid",
                    "unsupported CBSI mint-request entrypoint",
                ));
            }
        }
    }
    let arguments = encode_contract_argument_record(
        program.prepared_contract(),
        &entrypoint,
        normalized_payload.as_ref(),
    )
    .map_err(conversion_error)?;
    let signed_arguments =
        bound_signed_contract_arguments(arguments.clone()).map_err(conversion_error)?;
    let creation_time_ms = creation_time_ms.unwrap_or_else(current_time_millis);
    let attempt_created_at_ms = NonZeroU64::new(creation_time_ms).ok_or_else(|| {
        multisig_selector_validation_error("positive Propose creation_time_ms is required")
    })?;
    let mut tx_metadata = build_contract_call_metadata(
        &manifest,
        &contract_address,
        &code_hash,
        contract_alias.as_ref(),
        Some(&entrypoint),
        normalized_payload.as_ref(),
    );
    tx_metadata.insert(
        Name::from_str("contract_attempt_created_at_ms").expect("static metadata key"),
        IrohaJson::new(attempt_created_at_ms.get()),
    );
    let (proposal_instructions, proposal_hash) = build_multisig_contract_call_instructions(
        &multisig_account_id,
        &contract_address,
        contract_alias.as_ref(),
        &entrypoint,
        normalized_payload.as_ref(),
        arguments.as_deref(),
        &manifest,
        &code_hash,
        attempt_created_at_ms,
    )?;
    let proposal_id = hex::encode(proposal_hash.as_ref());
    let instructions_hash = proposal_id.clone();
    let propose_instruction =
        MultisigPropose::new(multisig_account_id.clone(), proposal_instructions, None);
    let will_execute = {
        let mut approvals = BTreeSet::new();
        approvals.insert(signer_account_id.clone());
        approvals_reach_quorum(&spec, &approvals)
    };
    let mut transaction_instructions = vec![dm::InstructionBox::from(propose_instruction)];
    if will_execute {
        transaction_instructions.push(dm::InstructionBox::from(MultisigApprove::new(
            multisig_account_id.clone(),
            proposal_hash.clone(),
        )));
    }
    let mut builder = dm::TransactionBuilder::new(
        *state.network_id_ref(),
        signer_account_id.clone().into(),
        iroha_data_model::transaction::FeePaymentIntent::authority(Vec::new(), None),
    );
    builder.set_creation_time(Duration::from_millis(creation_time_ms));
    let builder = builder
        .with_fee_payment_intent(fee_payment.clone())
        .with_metadata(tx_metadata.clone())
        .with_instructions(transaction_instructions);
    let builder = quote_app_api_transaction_builder(
        builder,
        queue.as_ref(),
        state.as_ref(),
        ENDPOINT_CONTRACTS_CALL_MULTISIG_PROPOSE,
    )?;
    let fee_payment = builder.payload().fee_payment.clone();
    let response = if public_key_hex.is_some() || signature_b64.is_some() {
        let signature = decode_app_api_detached_authority_signature(
            public_key_hex.as_deref(),
            signature_b64.as_deref(),
            &signer_account_id,
            "public_key_hex does not match signer_account_id",
        )?;
        let tx = builder.build_with_signature(signature);
        tx.verify_signature().map_err(|err| {
            conversion_error(format!(
                "multisig contract-call propose detached signature verification failed: {err}"
            ))
        })?;
        let tx_hash_hex = hex::encode(tx.hash().as_ref());
        let routing_plan = if will_execute {
            Some(multisig_immediate_execution_routing_plan(
                queue.as_ref(),
                state.as_ref(),
                &signer_account_id,
                creation_time_ms,
                fee_payment.clone(),
                tx_metadata.clone(),
                dm::Executable::ContractCall(
                    iroha_data_model::transaction::executable::ContractInvocation {
                        contract_address: contract_address.clone(),
                        expected_code_hash: code_hash,
                        entrypoint: entrypoint.clone(),
                        arguments: signed_arguments.clone(),
                    },
                ),
                ENDPOINT_CONTRACTS_CALL_MULTISIG_PROPOSE,
            )?)
        } else {
            None
        };
        handle_transaction_with_metrics_and_routing_plan(
            queue,
            Arc::clone(&state),
            tx,
            telemetry,
            routing_plan,
            ENDPOINT_CONTRACTS_CALL_MULTISIG_PROPOSE,
        )
        .await?;
        if wait_for_multisig_proposal_record_visibility(
            state.as_ref(),
            &multisig_account_id,
            &spec,
            &proposal_hash,
        )
        .await?
        .is_none()
        {
            iroha_logger::warn!(
                multisig_account_id = %multisig_account_id,
                proposal_id = %proposal_id,
                "submitted multisig contract-call proposal did not become visible within the wait window"
            );
        }
        MultisigContractCallResponseDto {
            ok: true,
            resolved_multisig_account_id: multisig_account_id.clone(),
            submitted: true,
            proposal_id: Some(proposal_id),
            instructions_hash: Some(instructions_hash),
            tx_hash_hex: Some(tx_hash_hex.clone()),
            // A quorum-reaching proposal carries MultisigPropose and
            // MultisigApprove in this same transaction. The nested contract
            // call therefore has the same authoritative finality identity as
            // the submitted outer transaction.
            executed_tx_hash_hex: will_execute.then_some(tx_hash_hex),
            creation_time_ms: Some(creation_time_ms),
            fee_payment: fee_payment.clone(),
            transaction_payload_b64: None,
            signing_message_b64: None,
        }
    } else {
        let draft = app_api_transaction_draft(&builder);
        MultisigContractCallResponseDto {
            ok: true,
            resolved_multisig_account_id: multisig_account_id,
            submitted: false,
            proposal_id: Some(proposal_id),
            instructions_hash: Some(instructions_hash),
            tx_hash_hex: None,
            executed_tx_hash_hex: None,
            creation_time_ms: Some(creation_time_ms),
            fee_payment: fee_payment.clone(),
            transaction_payload_b64: Some(draft.transaction_payload_b64),
            signing_message_b64: Some(draft.signing_message_b64),
        }
    };
    Ok(JsonBody(response).into_response())
}
/// POST /v1/contracts/call/multisig/approve — approve a multisig participation envelope
/// for a contract call.
#[iroha_futures::telemetry_future]
pub async fn handle_post_contract_call_multisig_approve(
    queue: Arc<Queue>,
    state: Arc<CoreState>,
    telemetry: MaybeTelemetry,
    NoritoJson(req): NoritoJson<MultisigContractCallApproveDto>,
) -> Result<Response> {
    use iroha_data_model::prelude as dm;
    use iroha_executor_data_model::isi::multisig::MultisigApprove;
    let MultisigContractCallApproveDto {
        selector,
        signer_account_id,
        public_key_hex,
        signature_b64,
        creation_time_ms,
        fee_payment,
        proposal_id,
        instructions_hash,
        contract_alias,
        entrypoint,
        payload,
    } = req;
    validate_app_api_fee_payment(&fee_payment, false)?;
    reject_unverified_multisig_alias_selector(&selector)?;
    let (multisig_account_id, _spec) =
        resolve_multisig_account_and_spec(&state, &selector, Some(&signer_account_id))?;
    let (hash_literal, instructions_hash) =
        resolve_multisig_proposal_hash(proposal_id.clone(), instructions_hash)?;
    let proposal_id_literal = proposal_id
        .as_deref()
        .map(str::trim)
        .filter(|value| !value.is_empty())
        .map(str::to_owned);
    let proposal_state = load_multisig_active_proposal_state_optional(
        state.as_ref(),
        &multisig_account_id,
        &instructions_hash,
    )?
    .ok_or_else(multisig_not_found_error)?;
    validate_multisig_active_proposal_binding(
        &multisig_account_id,
        &instructions_hash,
        &proposal_state,
    )?;
    let proposal = proposal_value_from_state(proposal_state);
    let exact_target = {
        let world = state.world_view();
        exact_multisig_contract_call_target_with_world(
            &world,
            &multisig_account_id,
            &proposal,
        )
        .ok_or_else(|| {
            multisig_selector_conflict_error(
                "multisig_contract_target_invalid",
                "the selected proposal is not an exact, currently deployed contract-call envelope",
            )
        })?
    };
    if exact_target.contract_alias != contract_alias
        || exact_target.contract_entrypoint != entrypoint
        || exact_target.payload != payload
    {
        return Err(multisig_selector_conflict_error(
            "multisig_contract_target_mismatch",
            "the selected proposal does not match the required contract alias, entrypoint, and payload",
        ));
    }
    let approve_instruction = MultisigApprove::new(multisig_account_id.clone(), instructions_hash);
    let creation_time_ms = creation_time_ms.unwrap_or_else(current_time_millis);
    let mut builder = dm::TransactionBuilder::new(
        *state.network_id_ref(),
        signer_account_id.clone().into(),
        iroha_data_model::transaction::FeePaymentIntent::authority(Vec::new(), None),
    );
    builder.set_creation_time(Duration::from_millis(creation_time_ms));
    let builder = builder
        .with_fee_payment_intent(fee_payment)
        .with_instructions([dm::InstructionBox::from(approve_instruction)]);
    let builder = quote_app_api_transaction_builder(
        builder,
        queue.as_ref(),
        state.as_ref(),
        ENDPOINT_CONTRACTS_CALL_MULTISIG_APPROVE,
    )?;
    let fee_payment = builder.payload().fee_payment.clone();
    let response = if public_key_hex.is_some() || signature_b64.is_some() {
        let signature = decode_app_api_detached_authority_signature(
            public_key_hex.as_deref(),
            signature_b64.as_deref(),
            &signer_account_id,
            "public_key_hex does not match signer_account_id",
        )?;
        let tx = builder.build_with_signature(signature);
        tx.verify_signature().map_err(|err| {
            conversion_error(format!(
                "multisig contract-call approve detached signature verification failed: {err}"
            ))
        })?;
        let tx_hash_hex = hex::encode(tx.hash().as_ref());
        handle_transaction_with_metrics(
            queue,
            state,
            tx,
            telemetry,
            ENDPOINT_CONTRACTS_CALL_MULTISIG_APPROVE,
        )
        .await?;
        MultisigContractCallResponseDto {
            ok: true,
            resolved_multisig_account_id: multisig_account_id.clone(),
            submitted: true,
            proposal_id: proposal_id_literal,
            instructions_hash: Some(hash_literal),
            tx_hash_hex: Some(tx_hash_hex.clone()),
            executed_tx_hash_hex: None,
            creation_time_ms: Some(creation_time_ms),
            fee_payment: fee_payment.clone(),
            transaction_payload_b64: None,
            signing_message_b64: None,
        }
    } else {
        let draft = app_api_transaction_draft(&builder);
        MultisigContractCallResponseDto {
            ok: true,
            resolved_multisig_account_id: multisig_account_id,
            submitted: false,
            proposal_id: proposal_id_literal,
            instructions_hash: Some(hash_literal),
            tx_hash_hex: None,
            executed_tx_hash_hex: None,
            creation_time_ms: Some(creation_time_ms),
            fee_payment: fee_payment.clone(),
            transaction_payload_b64: Some(draft.transaction_payload_b64),
            signing_message_b64: Some(draft.signing_message_b64),
        }
    };
    Ok(JsonBody(response).into_response())
}
/// POST /v1/multisig/cancel — cancel a multisig proposal through a multisig proposal or approval.
#[iroha_futures::telemetry_future]
pub async fn handle_post_multisig_cancel(
    queue: Arc<Queue>,
    state: Arc<CoreState>,
    telemetry: MaybeTelemetry,
    NoritoJson(req): NoritoJson<MultisigCancelRequestDto>,
) -> Result<Response> {
    use iroha_data_model::prelude as dm;
    use iroha_executor_data_model::isi::multisig::{
        MultisigApprove, MultisigCancel, MultisigPropose,
    };
    let MultisigCancelRequestDto {
        selector,
        signer_account_id,
        public_key_hex,
        signature_b64,
        creation_time_ms,
        fee_payment,
        proposal_id,
        instructions_hash,
    } = req;
    validate_app_api_fee_payment(&fee_payment, false)?;
    reject_unverified_multisig_alias_selector(&selector)?;
    let (multisig_account_id, spec) =
        resolve_multisig_account_and_spec(&state, &selector, Some(&signer_account_id))?;
    let (target_hash_literal, target_instructions_hash) =
        resolve_multisig_proposal_hash(proposal_id, instructions_hash)?;
    let target_record = load_multisig_proposal_record(
        &state,
        &multisig_account_id,
        &spec,
        &target_instructions_hash,
    )?
    .ok_or_else(multisig_not_found_error)?;
    if !matches!(
        target_record.status,
        MultisigProposalStatus::CollectingSignatures
    ) {
        return Err(conversion_error(format!(
            "target proposal is not cancelable in status {}",
            target_record.status.as_str()
        )));
    }
    let cancel_instruction =
        MultisigCancel::new(multisig_account_id.clone(), target_instructions_hash);
    let cancel_instructions = vec![dm::InstructionBox::from(cancel_instruction)];
    let cancel_hash = HashOf::new(&cancel_instructions);
    let cancel_hash_literal = cancel_hash.to_string();
    let existing_cancel_state =
        load_multisig_active_proposal_state_optional(&state, &multisig_account_id, &cancel_hash)?;
    let (action, creation_time_ms, builder) = if existing_cancel_state.is_some() {
        let approve_instruction = MultisigApprove::new(multisig_account_id.clone(), cancel_hash);
        let creation_time_ms = creation_time_ms.unwrap_or_else(current_time_millis);
        let mut builder = dm::TransactionBuilder::new(
            *state.network_id_ref(),
            signer_account_id.clone().into(),
            iroha_data_model::transaction::FeePaymentIntent::authority(Vec::new(), None),
        );
        builder.set_creation_time(Duration::from_millis(creation_time_ms));
        (
            "APPROVE".to_owned(),
            creation_time_ms,
            builder
                .with_fee_payment_intent(fee_payment.clone())
                .with_instructions([dm::InstructionBox::from(approve_instruction)]),
        )
    } else {
        let propose_instruction =
            MultisigPropose::new(multisig_account_id.clone(), cancel_instructions, None);
        let creation_time_ms = creation_time_ms.unwrap_or_else(current_time_millis);
        let mut builder = dm::TransactionBuilder::new(
            *state.network_id_ref(),
            signer_account_id.clone().into(),
            iroha_data_model::transaction::FeePaymentIntent::authority(Vec::new(), None),
        );
        builder.set_creation_time(Duration::from_millis(creation_time_ms));
        (
            "PROPOSE".to_owned(),
            creation_time_ms,
            builder
                .with_fee_payment_intent(fee_payment)
                .with_instructions([dm::InstructionBox::from(propose_instruction)]),
        )
    };
    let builder = quote_app_api_transaction_builder(
        builder,
        queue.as_ref(),
        state.as_ref(),
        ENDPOINT_MULTISIG_CANCEL,
    )?;
    let fee_payment = builder.payload().fee_payment.clone();
    let response = if public_key_hex.is_some() || signature_b64.is_some() {
        let signature = decode_app_api_detached_authority_signature(
            public_key_hex.as_deref(),
            signature_b64.as_deref(),
            &signer_account_id,
            "public_key_hex does not match signer_account_id",
        )?;
        let tx = builder.build_with_signature(signature);
        tx.verify_signature().map_err(|err| {
            conversion_error(format!(
                "multisig cancel detached signature verification failed: {err}"
            ))
        })?;
        let tx_hash_hex = hex::encode(tx.hash().as_ref());
        handle_transaction_with_metrics(
            queue,
            Arc::clone(&state),
            tx,
            telemetry,
            ENDPOINT_MULTISIG_CANCEL,
        )
        .await?;
        if action == "PROPOSE"
            && wait_for_multisig_proposal_record_visibility(
                state.as_ref(),
                &multisig_account_id,
                &spec,
                &cancel_hash,
            )
            .await?
            .is_none()
        {
            iroha_logger::warn!(
                multisig_account_id = %multisig_account_id,
                proposal_id = %cancel_hash_literal,
                "submitted multisig cancel proposal did not become visible within the wait window"
            );
        }
        MultisigCancelResponseDto {
            ok: true,
            resolved_multisig_account_id: multisig_account_id.clone(),
            submitted: true,
            action: action.clone(),
            target_proposal_id: target_hash_literal.clone(),
            target_instructions_hash: target_hash_literal.clone(),
            cancel_proposal_id: cancel_hash_literal.clone(),
            cancel_instructions_hash: cancel_hash_literal.clone(),
            tx_hash_hex: Some(tx_hash_hex),
            executed_tx_hash_hex: None,
            creation_time_ms: Some(creation_time_ms),
            fee_payment: fee_payment.clone(),
            transaction_payload_b64: None,
            signing_message_b64: None,
        }
    } else {
        let draft = app_api_transaction_draft(&builder);
        MultisigCancelResponseDto {
            ok: true,
            resolved_multisig_account_id: multisig_account_id,
            submitted: false,
            action,
            target_proposal_id: target_hash_literal.clone(),
            target_instructions_hash: target_hash_literal,
            cancel_proposal_id: cancel_hash_literal.clone(),
            cancel_instructions_hash: cancel_hash_literal,
            tx_hash_hex: None,
            executed_tx_hash_hex: None,
            creation_time_ms: Some(creation_time_ms),
            fee_payment: fee_payment.clone(),
            transaction_payload_b64: Some(draft.transaction_payload_b64),
            signing_message_b64: Some(draft.signing_message_b64),
        }
    };
    Ok(JsonBody(response).into_response())
}
/// POST /v1/multisig/propose — propose a generic multisig instruction batch.
#[iroha_futures::telemetry_future]
pub async fn handle_post_multisig_propose(
    queue: Arc<Queue>,
    state: Arc<CoreState>,
    telemetry: MaybeTelemetry,
    NoritoJson(req): NoritoJson<MultisigProposeDtoV1>,
) -> Result<Response> {
    use iroha_data_model::prelude as dm;
    use iroha_executor_data_model::isi::multisig::{MultisigApprove, MultisigPropose};
    use iroha_primitives::const_vec::ConstVec;
    let MultisigProposeDtoV1 {
        selector,
        signer_account_id,
        public_key_hex,
        signature_b64,
        creation_time_ms,
        fee_payment,
        memo,
        validation_fee_assessment,
        instructions,
    } = req;
    validate_app_api_fee_payment(&fee_payment, false)?;
    let memo = normalize_transaction_memo(memo);
    reject_unverified_multisig_alias_selector(&selector)?;
    let (multisig_account_id, spec) =
        resolve_multisig_account_and_spec(&state, &selector, Some(&signer_account_id))?;
    let mut proposal_instructions = instructions;
    if proposal_instructions.iter().any(|instruction| {
        instruction
            .as_any()
            .downcast_ref::<dm::Log>()
            .is_some_and(|log| {
                log.msg
                    .starts_with(iroha_core::retail_fee::ASSESSMENT_MARKER_PREFIX)
            })
    }) {
        return Err(conversion_error(
            "multisig instructions must not contain a caller-supplied fee assessment marker".into(),
        ));
    }
    if let Some(assessment) = &validation_fee_assessment {
        if assessment.account_id != multisig_account_id {
            return Err(conversion_error(
                "retail fee assessment must belong to the multisig execution account".into(),
            ));
        }
        let bytes = norito::encode_canonical(assessment)
            .map_err(|error| conversion_error(error.to_string()))?;
        proposal_instructions.push(
            dm::Log::new(
                dm::Level::TRACE,
                format!(
                    "{}{}",
                    iroha_core::retail_fee::ASSESSMENT_MARKER_PREFIX,
                    hex::encode(bytes)
                ),
            )
            .into(),
        );
    }
    let proposal_hash = HashOf::new(&proposal_instructions);
    let proposal_id = hex::encode(proposal_hash.as_ref());
    let instructions_hash = proposal_id.clone();
    let propose_instruction = MultisigPropose::new(
        multisig_account_id.clone(),
        proposal_instructions.clone(),
        None,
    );
    let will_execute = {
        let mut approvals = BTreeSet::new();
        approvals.insert(signer_account_id.clone());
        approvals_reach_quorum(&spec, &approvals)
    };
    let mut transaction_instructions = vec![dm::InstructionBox::from(propose_instruction)];
    if will_execute {
        transaction_instructions.push(dm::InstructionBox::from(MultisigApprove::new(
            multisig_account_id.clone(),
            proposal_hash.clone(),
        )));
    }
    let creation_time_ms = creation_time_ms.unwrap_or_else(current_time_millis);
    let mut builder = dm::TransactionBuilder::new(
        *state.network_id_ref(),
        signer_account_id.clone().into(),
        iroha_data_model::transaction::FeePaymentIntent::authority(Vec::new(), None),
    );
    builder.set_creation_time(Duration::from_millis(creation_time_ms));
    // The authenticated proposal marker is the sole assessment carrier. Repeating
    // it in outer metadata would double-bind when the proposer reaches quorum.
    let tx_metadata = build_multisig_propose_metadata(memo.as_deref());
    let builder = builder
        .with_fee_payment_intent(fee_payment.clone())
        .with_metadata(tx_metadata.clone())
        .with_instructions(transaction_instructions);
    let builder = quote_app_api_transaction_builder(
        builder,
        queue.as_ref(),
        state.as_ref(),
        ENDPOINT_MULTISIG_PROPOSE,
    )?;
    let fee_payment = builder.payload().fee_payment.clone();
    let response = if public_key_hex.is_some() || signature_b64.is_some() {
        let signature = decode_app_api_detached_authority_signature(
            public_key_hex.as_deref(),
            signature_b64.as_deref(),
            &signer_account_id,
            "public_key_hex does not match signer_account_id",
        )?;
        let tx = builder.build_with_signature(signature);
        tx.verify_signature().map_err(|err| {
            conversion_error(format!(
                "multisig propose detached signature verification failed: {err}"
            ))
        })?;
        let tx_hash_hex = hex::encode(tx.hash().as_ref());
        let routing_plan = if will_execute {
            Some(multisig_immediate_execution_routing_plan(
                queue.as_ref(),
                state.as_ref(),
                &signer_account_id,
                creation_time_ms,
                fee_payment.clone(),
                tx_metadata.clone(),
                dm::Executable::Instructions(ConstVec::from(proposal_instructions.clone())),
                ENDPOINT_MULTISIG_PROPOSE,
            )?)
        } else {
            None
        };
        handle_transaction_with_metrics_and_routing_plan(
            queue,
            Arc::clone(&state),
            tx,
            telemetry,
            routing_plan,
            ENDPOINT_MULTISIG_PROPOSE,
        )
        .await?;
        if wait_for_multisig_proposal_record_visibility(
            state.as_ref(),
            &multisig_account_id,
            &spec,
            &proposal_hash,
        )
        .await?
        .is_none()
        {
            iroha_logger::warn!(
                multisig_account_id = %multisig_account_id,
                proposal_id = %proposal_id,
                "submitted multisig proposal did not become visible within the wait window"
            );
        }
        MultisigContractCallResponseDto {
            ok: true,
            resolved_multisig_account_id: multisig_account_id.clone(),
            submitted: true,
            proposal_id: Some(proposal_id),
            instructions_hash: Some(instructions_hash),
            tx_hash_hex: Some(tx_hash_hex.clone()),
            // The quorum-one fast path executes the proposed instruction
            // batch atomically in this same transaction. Returning its
            // hash lets clients distinguish completed value movement from
            // a proposal that is only collecting signatures.
            executed_tx_hash_hex: will_execute.then_some(tx_hash_hex),
            creation_time_ms: Some(creation_time_ms),
            fee_payment: fee_payment.clone(),
            transaction_payload_b64: None,
            signing_message_b64: None,
        }
    } else {
        let draft = app_api_transaction_draft(&builder);
        MultisigContractCallResponseDto {
            ok: true,
            resolved_multisig_account_id: multisig_account_id,
            submitted: false,
            proposal_id: Some(proposal_id),
            instructions_hash: Some(instructions_hash),
            tx_hash_hex: None,
            executed_tx_hash_hex: None,
            creation_time_ms: Some(creation_time_ms),
            fee_payment: fee_payment.clone(),
            transaction_payload_b64: Some(draft.transaction_payload_b64),
            signing_message_b64: Some(draft.signing_message_b64),
        }
    };
    Ok(JsonBody(response).into_response())
}
/// POST /v1/multisig/approve — approve a generic multisig proposal.
#[iroha_futures::telemetry_future]
pub async fn handle_post_multisig_approve(
    queue: Arc<Queue>,
    state: Arc<CoreState>,
    telemetry: MaybeTelemetry,
    NoritoJson(req): NoritoJson<MultisigApproveDto>,
) -> Result<Response> {
    use iroha_data_model::prelude as dm;
    use iroha_executor_data_model::isi::multisig::MultisigApprove;
    let MultisigApproveDto {
        selector,
        signer_account_id,
        public_key_hex,
        signature_b64,
        creation_time_ms,
        fee_payment,
        proposal_id,
        instructions_hash,
    } = req;
    validate_app_api_fee_payment(&fee_payment, false)?;
    reject_unverified_multisig_alias_selector(&selector)?;
    let (multisig_account_id, _spec) =
        resolve_multisig_account_and_spec(&state, &selector, Some(&signer_account_id))?;
    let (hash_literal, instructions_hash) =
        resolve_multisig_proposal_hash(proposal_id.clone(), instructions_hash)?;
    let proposal_id_literal = proposal_id
        .as_deref()
        .map(str::trim)
        .filter(|value| !value.is_empty())
        .map(str::to_owned);
    let approve_instruction = MultisigApprove::new(multisig_account_id.clone(), instructions_hash);
    let creation_time_ms = creation_time_ms.unwrap_or_else(current_time_millis);
    let mut builder = dm::TransactionBuilder::new(
        *state.network_id_ref(),
        signer_account_id.clone().into(),
        iroha_data_model::transaction::FeePaymentIntent::authority(Vec::new(), None),
    );
    builder.set_creation_time(Duration::from_millis(creation_time_ms));
    let builder = builder
        .with_fee_payment_intent(fee_payment)
        .with_instructions([dm::InstructionBox::from(approve_instruction)]);
    let builder = quote_app_api_transaction_builder(
        builder,
        queue.as_ref(),
        state.as_ref(),
        ENDPOINT_MULTISIG_APPROVE,
    )?;
    let fee_payment = builder.payload().fee_payment.clone();
    let response = if public_key_hex.is_some() || signature_b64.is_some() {
        let signature = decode_app_api_detached_authority_signature(
            public_key_hex.as_deref(),
            signature_b64.as_deref(),
            &signer_account_id,
            "public_key_hex does not match signer_account_id",
        )?;
        let tx = builder.build_with_signature(signature);
        tx.verify_signature().map_err(|err| {
            conversion_error(format!(
                "multisig approve detached signature verification failed: {err}"
            ))
        })?;
        let tx_hash_hex = hex::encode(tx.hash().as_ref());
        handle_transaction_with_metrics(queue, state, tx, telemetry, ENDPOINT_MULTISIG_APPROVE)
            .await?;
        MultisigContractCallResponseDto {
            ok: true,
            resolved_multisig_account_id: multisig_account_id.clone(),
            submitted: true,
            proposal_id: proposal_id_literal,
            instructions_hash: Some(hash_literal),
            tx_hash_hex: Some(tx_hash_hex.clone()),
            executed_tx_hash_hex: None,
            creation_time_ms: Some(creation_time_ms),
            fee_payment: fee_payment.clone(),
            transaction_payload_b64: None,
            signing_message_b64: None,
        }
    } else {
        let draft = app_api_transaction_draft(&builder);
        MultisigContractCallResponseDto {
            ok: true,
            resolved_multisig_account_id: multisig_account_id,
            submitted: false,
            proposal_id: proposal_id_literal,
            instructions_hash: Some(hash_literal),
            tx_hash_hex: None,
            executed_tx_hash_hex: None,
            creation_time_ms: Some(creation_time_ms),
            fee_payment: fee_payment.clone(),
            transaction_payload_b64: Some(draft.transaction_payload_b64),
            signing_message_b64: Some(draft.signing_message_b64),
        }
    };
    Ok(JsonBody(response).into_response())
}
