fn mk_record_from_inputs(
    inputs: VkRecordInputs,
) -> Result<iroha_data_model::proof::VerifyingKeyRecord> {
    use iroha_core_zk::hash_vk;
    use iroha_data_model::{
        confidential::ConfidentialStatus,
        proof::{VerifyingKeyBox, VerifyingKeyRecord},
    };
    let VkRecordInputs {
        backend,
        version,
        status,
        vk_bytes,
        commitment_hex,
        circuit_id,
        public_inputs_schema_hash_hex,
        curve,
        gas_schedule_id,
        vk_len,
        max_proof_bytes,
        metadata_uri_cid,
        vk_bytes_cid,
        activation_height,
        withdraw_height,
    } = inputs;
    let backend_tag = iroha_core_zk::verifier_backend_registry_tag_v1(backend.as_str())
        .ok_or_else(|| {
            Error::Query(iroha_data_model::ValidationFail::QueryFailed(
                iroha_data_model::query::error::QueryExecutionFail::Conversion(format!(
                    "unsupported generic OpenVerify backend `{backend}`"
                )),
            ))
        })?;
    let mut key_opt = None;
    let commitment: [u8; 32];
    let vk_len_value;
    if let Some(bytes) = vk_bytes {
        let vk = VerifyingKeyBox::new(backend.as_str().into(), bytes);
        let h = hash_vk(&vk);
        if let Some(hex) = &commitment_hex {
            let parsed = parse_commitment_hex(hex)?;
            if parsed != h {
                return Err(Error::Query(iroha_data_model::ValidationFail::QueryFailed(
                    iroha_data_model::query::error::QueryExecutionFail::Conversion(
                        "commitment mismatch with provided vk_bytes".into(),
                    ),
                )));
            }
        }
        commitment = h;
        let actual_len = vk.bytes.len() as u32;
        if let Some(explicit_len) = vk_len {
            if explicit_len != actual_len {
                return Err(Error::Query(iroha_data_model::ValidationFail::QueryFailed(
                    iroha_data_model::query::error::QueryExecutionFail::Conversion(
                        "vk_len mismatch with provided vk_bytes".into(),
                    ),
                )));
            }
        }
        vk_len_value = actual_len;
        key_opt = Some(vk);
    } else if let Some(hex) = commitment_hex {
        commitment = parse_commitment_hex(&hex)?;
        let explicit_len = vk_len.ok_or_else(|| {
            Error::Query(iroha_data_model::ValidationFail::QueryFailed(
                iroha_data_model::query::error::QueryExecutionFail::Conversion(
                    "vk_len required when vk_bytes omitted".into(),
                ),
            ))
        })?;
        if explicit_len == 0 {
            return Err(Error::Query(iroha_data_model::ValidationFail::QueryFailed(
                iroha_data_model::query::error::QueryExecutionFail::Conversion(
                    "vk_len must be > 0".into(),
                ),
            )));
        }
        vk_len_value = explicit_len;
    } else {
        return Err(Error::Query(iroha_data_model::ValidationFail::QueryFailed(
            iroha_data_model::query::error::QueryExecutionFail::Conversion(
                "provide either vk_bytes or commitment_hex".into(),
            ),
        )));
    }
    let schema_hash = parse_hex32_str(
        &public_inputs_schema_hash_hex,
        "public_inputs_schema_hash_hex",
    )?;
    if matches!(gas_schedule_id.as_deref(), Some(id) if id.trim().is_empty()) {
        return Err(Error::Query(iroha_data_model::ValidationFail::QueryFailed(
            iroha_data_model::query::error::QueryExecutionFail::Conversion(
                "gas_schedule_id must not be empty".into(),
            ),
        )));
    }
    if activation_height
        .zip(withdraw_height)
        .is_some_and(|(act, withdraw)| act >= withdraw)
    {
        return Err(Error::Query(iroha_data_model::ValidationFail::QueryFailed(
            iroha_data_model::query::error::QueryExecutionFail::Conversion(
                "withdraw_height must be > activation_height".into(),
            ),
        )));
    }
    let mut record = VerifyingKeyRecord::new_with_owner(
        version,
        circuit_id,
        None,
        "core",
        backend_tag,
        curve.unwrap_or_else(|| "unknown".into()),
        schema_hash,
        commitment,
    );
    record.vk_len = vk_len_value;
    record.max_proof_bytes = max_proof_bytes.unwrap_or(0);
    record.status = status.unwrap_or(ConfidentialStatus::Active);
    record.metadata_uri_cid = metadata_uri_cid;
    record.vk_bytes_cid = vk_bytes_cid;
    record.activation_height = activation_height;
    record.withdraw_height = withdraw_height;
    record.key = key_opt;
    record.gas_schedule_id = gas_schedule_id;
    Ok(record)
}
fn vk_record_to_json(rec: &iroha_data_model::proof::VerifyingKeyRecord) -> norito::json::Value {
    use crate::json_value;
    use iroha_data_model::confidential::ConfidentialStatus;
    let mut m = norito::json::Map::new();
    m.insert(
        "version".into(),
        norito::json::Value::from(rec.version as u64),
    );
    m.insert(
        "circuit_id".into(),
        norito::json::Value::from(rec.circuit_id.clone()),
    );
    m.insert(
        "owner_manifest_id".into(),
        json_value(&rec.owner_manifest_id),
    );
    m.insert(
        "namespace".into(),
        norito::json::Value::from(rec.namespace.clone()),
    );
    m.insert("backend".into(), json_value(&rec.backend));
    m.insert("curve".into(), norito::json::Value::from(rec.curve.clone()));
    m.insert(
        "public_inputs_schema_hash".into(),
        norito::json::Value::from(hex::encode(rec.public_inputs_schema_hash)),
    );
    m.insert(
        "commitment".into(),
        norito::json::Value::from(hex::encode(rec.commitment)),
    );
    m.insert(
        "vk_len".into(),
        norito::json::Value::from(rec.vk_len as u64),
    );
    m.insert(
        "max_proof_bytes".into(),
        norito::json::Value::from(rec.max_proof_bytes as u64),
    );
    m.insert("gas_schedule_id".into(), json_value(&rec.gas_schedule_id));
    m.insert("metadata_uri_cid".into(), json_value(&rec.metadata_uri_cid));
    m.insert("vk_bytes_cid".into(), json_value(&rec.vk_bytes_cid));
    m.insert(
        "activation_height".into(),
        json_value(&rec.activation_height),
    );
    m.insert("withdraw_height".into(), json_value(&rec.withdraw_height));
    let status_str = match rec.status {
        ConfidentialStatus::Active => "Active",
        ConfidentialStatus::Proposed => "Proposed",
        ConfidentialStatus::Withdrawn => "Withdrawn",
    };
    m.insert("status".into(), norito::json::Value::from(status_str));
    let key_value = if let Some(vk) = rec.key.as_ref() {
        let mut k = norito::json::Map::new();
        k.insert(
            "backend".into(),
            norito::json::Value::from(vk.backend.clone()),
        );
        k.insert(
            "bytes_b64".into(),
            norito::json::Value::from(base64::engine::general_purpose::STANDARD.encode(&vk.bytes)),
        );
        norito::json::Value::Object(k)
    } else {
        norito::json::Value::Null
    };
    m.insert("key".into(), key_value);
    norito::json::Value::Object(m)
}
fn vk_record_norito_base64(rec: &iroha_data_model::proof::VerifyingKeyRecord) -> Result<String> {
    let bytes = norito::to_bytes(rec).map_err(|err| {
        conversion_error(format!(
            "failed to encode verifying key record as Norito: {err}"
        ))
    })?;
    Ok(base64::engine::general_purpose::STANDARD.encode(bytes))
}
fn vk_detail_to_json(
    id: &iroha_data_model::proof::VerifyingKeyId,
    rec: &iroha_data_model::proof::VerifyingKeyRecord,
) -> Result<norito::json::Value> {
    let mut root = norito::json::Map::new();
    let mut id_map = norito::json::Map::new();
    id_map.insert(
        "backend".into(),
        norito::json::Value::from(id.backend.clone()),
    );
    id_map.insert("name".into(), norito::json::Value::from(id.name.clone()));
    root.insert("id".into(), norito::json::Value::Object(id_map));
    root.insert("record".into(), vk_record_to_json(rec));
    root.insert(
        "record_norito_base64".into(),
        norito::json::Value::from(vk_record_norito_base64(rec)?),
    );
    Ok(norito::json::Value::Object(root))
}
#[cfg(all(test, feature = "app_api"))]
mod vk_record_input_tests {
    use super::*;
    use iroha_data_model::confidential::ConfidentialStatus;
    fn sample_hex32(fill: u8) -> String {
        hex::encode([fill; 32])
    }
    routing_test! { sync mk_record_from_inputs_sets_optional_fields
        let vk_bytes = vec![1, 2, 3, 4];
        let inputs = VkRecordInputs {
            backend: "pipa-r/pasta".to_string(),
            version: 1,
            status: Some(ConfidentialStatus::Active),
            vk_bytes: Some(vk_bytes.clone()),
            commitment_hex: None,
            circuit_id: "circuit_alpha".to_string(),
            public_inputs_schema_hash_hex: sample_hex32(0xAA),
            curve: Some("vesta".to_string()),
            gas_schedule_id: Some("sched_default".to_string()),
            vk_len: Some(vk_bytes.len() as u32),
            max_proof_bytes: Some(8192),
            metadata_uri_cid: Some("ipfs://metadata".to_string()),
            vk_bytes_cid: Some("ipfs://vk_bytes".to_string()),
            activation_height: Some(100),
            withdraw_height: Some(300),
        };
        let record = mk_record_from_inputs(inputs).expect("record created");
        assert_eq!(record.vk_len, vk_bytes.len() as u32);
        assert_eq!(record.max_proof_bytes, 8192);
        assert_eq!(record.metadata_uri_cid.as_deref(), Some("ipfs://metadata"));
        assert_eq!(record.vk_bytes_cid.as_deref(), Some("ipfs://vk_bytes"));
        assert_eq!(record.activation_height, Some(100));
        assert_eq!(record.withdraw_height, Some(300));
        assert!(record.key.is_some(), "stored vk bytes should be preserved");
        assert_eq!(record.gas_schedule_id.as_deref(), Some("sched_default"));
    }
    routing_test! { sync vk_record_detail_json_preserves_identity_and_exact_norito_archive
        let mut record = mk_record_from_inputs(VkRecordInputs {
            backend: "pipa-r/pasta".to_string(),
            version: 7,
            status: Some(ConfidentialStatus::Active),
            vk_bytes: Some(vec![1, 2, 3, 4]),
            commitment_hex: None,
            circuit_id: "pipa-r/pasta/confidential-unshield-change-v1".to_string(),
            public_inputs_schema_hash_hex: sample_hex32(0xA5),
            curve: Some("vesta".to_string()),
            gas_schedule_id: Some("native_pipa_r_default".to_string()),
            vk_len: Some(4),
            max_proof_bytes: Some(16_384),
            metadata_uri_cid: Some("ipfs://metadata".to_string()),
            vk_bytes_cid: Some("ipfs://vk".to_string()),
            activation_height: Some(10),
            withdraw_height: Some(20),
        })
        .expect("record created");
        record.namespace = "confidential_assets".to_owned();
        record.owner_manifest_id = Some("builtin:pipa-r/pasta/confidential-unshield-change-v1".to_owned());
        let id = iroha_data_model::proof::VerifyingKeyId::new(
            "pipa-r/pasta",
            "pipa-r/pasta/confidential-unshield-change-v1",
        );
        let detail = vk_detail_to_json(&id, &record).expect("build verifier record detail");
        let detail_object = detail.as_object().expect("verifier detail JSON object");
        let object = detail_object
            .get("record")
            .and_then(norito::json::Value::as_object)
            .expect("verifier record JSON object");
        assert_eq!(
            object
                .get("namespace")
                .and_then(norito::json::Value::as_str),
            Some(record.namespace.as_str())
        );
        assert_eq!(
            object
                .get("owner_manifest_id")
                .and_then(norito::json::Value::as_str),
            record.owner_manifest_id.as_deref()
        );
        let encoded = detail_object
            .get("record_norito_base64")
            .and_then(norito::json::Value::as_str)
            .expect("verifier record Norito archive");
        let archive = base64::engine::general_purpose::STANDARD
            .decode(encoded)
            .expect("decode verifier record archive base64");
        assert_eq!(
            archive,
            norito::to_bytes(&record).expect("canonical verifier record archive")
        );
        let decoded: iroha_data_model::proof::VerifyingKeyRecord =
            norito::decode_from_bytes(&archive).expect("decode verifier record archive");
        assert_eq!(&decoded.namespace, &record.namespace);
        assert_eq!(
            decoded.owner_manifest_id.as_ref(),
            record.owner_manifest_id.as_ref()
        );
        assert_eq!(decoded.key.as_ref(), record.key.as_ref());
        assert_eq!(decoded.activation_height, record.activation_height);
        assert_eq!(decoded.withdraw_height, record.withdraw_height);
        assert_eq!(decoded, record);
    }
    routing_test! { sync mk_record_from_inputs_rejects_protocol_names_as_generic_backends
        for backend in [
            "halo2/ipa/orchard",
            "groth16/bls12-377",
            "penumbra-masp",
            "monero-fcmp++",
            "sis-hints-anoncred-pq-v0",
            "sis-with-hints",
            "post-quantum-masp",
            "unknown/privacy/backend",
        ] {
            let error = mk_record_from_inputs(VkRecordInputs {
                backend: backend.to_string(),
                version: 1,
                status: Some(ConfidentialStatus::Proposed),
                vk_bytes: None,
                commitment_hex: Some(sample_hex32(0x11)),
                circuit_id: "pending_circuit".to_string(),
                public_inputs_schema_hash_hex: sample_hex32(0xAA),
                curve: Some("pending".to_string()),
                gas_schedule_id: Some("sched_default".to_string()),
                vk_len: Some(32),
                max_proof_bytes: Some(8192),
                metadata_uri_cid: None,
                vk_bytes_cid: None,
                activation_height: None,
                withdraw_height: None,
            })
            .expect_err("protocol names must not be accepted as generic verifier engines");
            assert!(
                error
                    .to_string()
                    .contains("unsupported generic OpenVerify backend"),
                "unexpected error for {backend}: {error}",
            );
        }
    }
    routing_test! { sync mk_record_requires_vk_len_without_bytes
        let res = mk_record_from_inputs(VkRecordInputs {
            backend: "pipa-r/pasta".to_string(),
            version: 1,
            status: Some(ConfidentialStatus::Active),
            vk_bytes: None,
            commitment_hex: Some(sample_hex32(0x11)),
            circuit_id: "circuit_alpha".to_string(),
            public_inputs_schema_hash_hex: sample_hex32(0x22),
            curve: Some("vesta".to_string()),
            gas_schedule_id: Some("sched_default".to_string()),
            vk_len: None,
            max_proof_bytes: None,
            metadata_uri_cid: None,
            vk_bytes_cid: None,
            activation_height: None,
            withdraw_height: None,
        });
        assert!(res.is_err());
    }
    routing_test! { sync mk_record_allows_missing_gas_schedule
        let record = mk_record_from_inputs(VkRecordInputs {
            backend: "pipa-r/pasta".to_string(),
            version: 1,
            status: Some(ConfidentialStatus::Active),
            vk_bytes: Some(vec![1, 2, 3]),
            commitment_hex: None,
            circuit_id: "circuit_alpha".to_string(),
            public_inputs_schema_hash_hex: sample_hex32(0x33),
            curve: Some("vesta".to_string()),
            gas_schedule_id: None,
            vk_len: Some(3),
            max_proof_bytes: None,
            metadata_uri_cid: None,
            vk_bytes_cid: None,
            activation_height: None,
            withdraw_height: None,
        })
        .expect("record created without optional gas schedule");
        assert!(record.gas_schedule_id.is_none());
    }
    routing_test! { sync mk_record_allows_withdrawn_status
        let record = mk_record_from_inputs(VkRecordInputs {
            backend: "pipa-r/pasta".to_string(),
            version: 1,
            status: Some(ConfidentialStatus::Withdrawn),
            vk_bytes: Some(vec![1, 2, 3]),
            commitment_hex: None,
            circuit_id: "circuit_alpha".to_string(),
            public_inputs_schema_hash_hex: sample_hex32(0x44),
            curve: Some("vesta".to_string()),
            gas_schedule_id: Some("sched_default".to_string()),
            vk_len: Some(3),
            max_proof_bytes: None,
            metadata_uri_cid: None,
            vk_bytes_cid: None,
            activation_height: None,
            withdraw_height: None,
        })
        .expect("withdrawn verifier records can be submitted by update routes");
        assert_eq!(record.status, ConfidentialStatus::Withdrawn);
    }
    routing_test! { sync mk_record_rejects_inconsistent_heights
        for withdraw_height in [100, 200] {
            let res = mk_record_from_inputs(VkRecordInputs {
                backend: "pipa-r/pasta".to_string(),
                version: 1,
                status: Some(ConfidentialStatus::Active),
                vk_bytes: Some(vec![1, 2, 3]),
                commitment_hex: None,
                circuit_id: "circuit_alpha".to_string(),
                public_inputs_schema_hash_hex: sample_hex32(0x55),
                curve: Some("vesta".to_string()),
                gas_schedule_id: Some("sched_default".to_string()),
                vk_len: Some(3),
                max_proof_bytes: None,
                metadata_uri_cid: None,
                vk_bytes_cid: None,
                activation_height: Some(200),
                withdraw_height: Some(withdraw_height),
            });
            assert!(res.is_err(), "withdraw height {withdraw_height} must be rejected");
        }
    }
}
/// POST /v1/zk/vk/register — prepare `RegisterVerifyingKey` for local signing.
pub async fn handle_post_vk_register(
    queue: Arc<Queue>,
    state: Arc<CoreState>,
    NoritoJson(req): NoritoJson<ZkVkRegisterDto>,
) -> Result<JsonBody<AppApiTransactionDraftDto>> {
    use iroha_data_model::{isi::verifying_keys, prelude as dm};
    let vk_record = mk_record_from_inputs(VkRecordInputs {
        backend: req.backend.clone(),
        version: req.version,
        status: req.status,
        vk_bytes: req.vk_bytes.clone(),
        commitment_hex: req.commitment_hex.clone(),
        circuit_id: req.circuit_id.clone(),
        public_inputs_schema_hash_hex: req.public_inputs_schema_hash_hex.clone(),
        curve: req.curve.clone(),
        gas_schedule_id: req.gas_schedule_id.clone(),
        vk_len: req.vk_len,
        max_proof_bytes: req.max_proof_bytes,
        metadata_uri_cid: req.metadata_uri_cid.clone(),
        vk_bytes_cid: req.vk_bytes_cid.clone(),
        activation_height: req.activation_height,
        withdraw_height: req.withdraw_height,
    })?;
    let id = VerifyingKeyId::new(req.backend.clone(), req.name.clone());
    let isi = verifying_keys::RegisterVerifyingKey {
        id,
        record: vk_record,
    };
    let builder = quote_app_api_transaction_builder(
        new_app_api_transaction_builder_from_state(state.as_ref(), req.authority.clone())
            .with_instructions(core::iter::once(dm::InstructionBox::from(isi))),
        queue.as_ref(),
        state.as_ref(),
        "/v1/zk/vk/register",
    )?;
    Ok(JsonBody(app_api_transaction_draft(&builder)))
}
