app_api_items! {
fn validate_sorafs_capacity_declaration_transaction(
    network_id: &NetworkId,
    transaction: &SignedTransaction,
) -> Result<CapacityDeclarationV1> {
    let register = validate_single_signed_instruction::<
        iroha_data_model::isi::sorafs::RegisterCapacityDeclaration,
    >(
        network_id,
        transaction,
        "sorafs_capacity_declaration_transaction_network_mismatch",
        "sorafs_capacity_declaration_transaction_signature_invalid",
        "sorafs_capacity_declaration_transaction_executable_invalid",
        "sorafs_capacity_declaration_transaction_instruction_count_invalid",
        "sorafs_capacity_declaration_transaction_instruction_invalid",
        "capacity declaration submission",
        "RegisterCapacityDeclaration",
    )?;
    if register.declaration.is_empty()
        || register.declaration.len() > SORAFS_CAPACITY_DECLARATION_PAYLOAD_MAX_BYTES
    {
        return Err(sorafs_pin_validation_error(
            "sorafs_capacity_declaration_payload_size_invalid",
            format!(
                "RegisterCapacityDeclaration.declaration must contain 1..={SORAFS_CAPACITY_DECLARATION_PAYLOAD_MAX_BYTES} bytes"
            ),
        ));
    }
    let declaration = norito::decode_from_bytes_with_limits::<CapacityDeclarationV1>(
        &register.declaration,
        SORAFS_CAPACITY_DECLARATION_DECODE_LIMITS,
    )
    .map_err(|error| {
        sorafs_pin_validation_error(
            "sorafs_capacity_declaration_payload_decode_failed",
            format!("invalid bounded CapacityDeclarationV1 payload: {error}"),
        )
    })?;
    let canonical = norito::to_bytes(&declaration).map_err(|error| {
        sorafs_pin_validation_error(
            "sorafs_capacity_declaration_payload_encode_failed",
            format!("failed to re-encode CapacityDeclarationV1 payload: {error}"),
        )
    })?;
    if canonical != register.declaration {
        return Err(sorafs_pin_validation_error(
            "sorafs_capacity_declaration_payload_noncanonical",
            "RegisterCapacityDeclaration.declaration must use canonical first-release Norito",
        ));
    }
    declaration
        .validate()
        .map_err(capacity_declaration_validation_error)?;
    Ok(declaration)
}
fn validate_sorafs_capacity_telemetry_transaction<'a>(
    network_id: &NetworkId,
    transaction: &'a SignedTransaction,
) -> Result<&'a iroha_data_model::isi::sorafs::RecordCapacityTelemetry> {
    let submit = validate_single_signed_instruction::<
        iroha_data_model::isi::sorafs::RecordCapacityTelemetry,
    >(
        network_id,
        transaction,
        "sorafs_capacity_telemetry_transaction_network_mismatch",
        "sorafs_capacity_telemetry_transaction_signature_invalid",
        "sorafs_capacity_telemetry_transaction_executable_invalid",
        "sorafs_capacity_telemetry_transaction_instruction_count_invalid",
        "sorafs_capacity_telemetry_transaction_instruction_invalid",
        "capacity telemetry submission",
        "RecordCapacityTelemetry",
    )?;
    let record = &submit.record;
    let invalid =
        |message| sorafs_pin_validation_error("sorafs_capacity_telemetry_record_invalid", message);
    if record.window_start_epoch > record.window_end_epoch {
        return Err(invalid(
            "capacity telemetry window_start_epoch must not exceed window_end_epoch",
        ));
    }
    if record.nonce == 0 || record.nonce != record.window_end_epoch {
        return Err(sorafs_pin_validation_error(
            "sorafs_capacity_telemetry_nonce_invalid",
            "capacity telemetry nonce must equal the non-zero window_end_epoch",
        ));
    }
    if record.effective_gib > record.declared_gib {
        return Err(invalid(
            "capacity telemetry effective_gib must not exceed declared_gib",
        ));
    }
    if record.utilised_gib > record.effective_gib {
        return Err(invalid(
            "capacity telemetry utilised_gib must not exceed effective_gib",
        ));
    }
    if record.orders_completed > record.orders_issued {
        return Err(invalid(
            "capacity telemetry orders_completed must not exceed orders_issued",
        ));
    }
    if record.uptime_bps > 10_000 || record.por_success_bps > 10_000 {
        return Err(invalid(
            "capacity telemetry success rates must not exceed 10_000 basis points",
        ));
    }
    if record.pdp_failures > record.pdp_challenges {
        return Err(invalid(
            "capacity telemetry pdp_failures must not exceed pdp_challenges",
        ));
    }
    if record.potr_breaches > record.potr_windows {
        return Err(invalid(
            "capacity telemetry potr_breaches must not exceed potr_windows",
        ));
    }
    Ok(submit)
}
#[iroha_futures::telemetry_future]
pub async fn handle_post_sorafs_register_capacity_declaration(
    queue: Arc<Queue>,
    state: Arc<CoreState>,
    telemetry: MaybeTelemetry,
    sorafs_limits: Arc<SorafsQuotaEnforcer>,
    transaction: SignedTransaction,
) -> Result<impl IntoResponse> {
    let declaration =
        validate_sorafs_capacity_declaration_transaction(state.network_id_ref(), &transaction)?;
    ensure_sorafs_quota_authority_registered(state.as_ref(), &transaction)?;
    let quota_subject = sorafs_transaction_quota_subject(&transaction);
    if let Err(err) = sorafs_limits.enforce(SorafsAction::CapacityDeclaration, &quota_subject) {
        return Err(quota_limit_error(err));
    }
    let response = RegisterCapacityDeclarationResponseDto {
        provider_id_hex: hex::encode(declaration.provider_id),
        status: "submitted".to_owned(),
        tx_hash_hex: hex::encode(transaction.hash().as_ref()),
        valid_from_epoch: declaration.valid_from,
        valid_until_epoch: declaration.valid_until,
    };
    handle_transaction_with_metrics(
        queue,
        state,
        transaction,
        telemetry,
        "/v1/sorafs/capacity/declare",
    )
    .await?;
    let mut response = infallible_pretty_json_response(&response, "{}");
    *response.status_mut() = axum::http::StatusCode::ACCEPTED;
    Ok(response)
}
#[iroha_futures::telemetry_future]
pub async fn handle_post_sorafs_record_capacity_telemetry(
    queue: Arc<Queue>,
    state: Arc<CoreState>,
    telemetry: MaybeTelemetry,
    sorafs_limits: Arc<SorafsQuotaEnforcer>,
    transaction: SignedTransaction,
) -> Result<impl IntoResponse> {
    let submit =
        validate_sorafs_capacity_telemetry_transaction(state.network_id_ref(), &transaction)?;
    ensure_sorafs_quota_authority_registered(state.as_ref(), &transaction)?;
    let quota_subject = sorafs_transaction_quota_subject(&transaction);
    let record = submit.record;
    let provider_id = record.provider_id;
    if let Err(err) = sorafs_limits.enforce(SorafsAction::CapacityTelemetry, &quota_subject) {
        return Err(quota_limit_error(err));
    }
    let response = RecordCapacityTelemetryResponseDto {
        provider_id_hex: hex::encode(provider_id.as_bytes()),
        window_start_epoch: record.window_start_epoch,
        window_end_epoch: record.window_end_epoch,
    };
    handle_transaction_with_metrics(
        queue,
        state,
        transaction,
        telemetry,
        "/v1/sorafs/capacity/telemetry",
    )
    .await?;
    Ok(infallible_pretty_json_response(&response, "{}"))
}
fn sorafs_transaction_quota_subject(transaction: &SignedTransaction) -> [u8; 32] {
    let mut hasher = blake3::Hasher::new();
    hasher.update(b"iroha:sorafs:control-plane-quota:v1\0");
    hasher.update(transaction.authority().to_string().as_bytes());
    *hasher.finalize().as_bytes()
}
fn ensure_sorafs_quota_authority_registered(
    state: &CoreState,
    transaction: &SignedTransaction,
) -> Result<()> {
    state
        .world_view()
        .account(transaction.authority())
        .map(|_| ())
        .map_err(|_| {
            sorafs_pin_validation_error(
                "sorafs_quota_authority_not_registered",
                "SoraFS control-plane quota authority must be a registered on-chain account",
            )
        })
}
#[iroha_futures::telemetry_future]
pub(crate) async fn handle_post_sorafs_record_por_proof(
    _telemetry: MaybeTelemetry,
    sorafs_node: sorafs_node::NodeHandle,
    sorafs_limits: Arc<SorafsQuotaEnforcer>,
    por_coordinator: Arc<sorafs::PorCoordinator>,
    proof: PorProofV1,
    authenticated_signer: PublicKey,
    admitted_provider_key: Vec<u8>,
) -> Result<impl IntoResponse> {
    verify_authenticated_por_proof(&proof, &authenticated_signer, &admitted_provider_key)?;
    if let Err(err) = sorafs_limits.enforce(SorafsAction::PorSubmission, &proof.provider_id) {
        return Err(quota_limit_error(err));
    }
    let pipeline = por_coordinator.lock_pipeline().await;
    let node_for_worker = sorafs_node.clone();
    let coordinator_for_worker = Arc::clone(&por_coordinator);
    let proof_for_worker = proof.clone();
    let (node_result, projection_result) = crate::panic_recovery::join_recoverable(
        crate::panic_recovery::spawn_blocking_recoverable(move || {
        // Keep serialization through physical completion: cancellation of the
        // HTTP future must not let a later authority delta overtake this one.
        let _pipeline = pipeline;
        match node_for_worker
            .record_por_proof_with_authority_update(&proof_for_worker, &admitted_provider_key)
        {
            Ok(update) => (
                Ok(()),
                coordinator_for_worker.apply_authoritative_update(update),
            ),
            Err(error) => {
                if error.disposition().invalidates_projection() {
                    coordinator_for_worker.invalidate_authoritative_projection();
                }
                (Err(error.into_tracker_error()), Ok(()))
            }
        }
    }),
    )
    .await
    .map_err(|error| {
        por_coordinator.invalidate_authoritative_projection();
        Error::Query(iroha_data_model::ValidationFail::InternalError(format!(
            "PoR proof persistence worker failed: {error}"
        )))
    })?;
    projection_result.map_err(por_coordinator_error)?;
    node_result.map_err(por_tracker_error)?;
    iroha_logger::info!(
        provider_id = %hex::encode(proof.provider_id),
        challenge_id = %hex::encode(proof.challenge_id),
        manifest_digest = %hex::encode(proof.manifest_digest),
        samples = proof.samples.len(),
        submitted_at = proof.submitted_at,
        "recorded SoraFS PoR proof"
    );
    let response = RecordPorSubmissionResponseDto {
        status: "accepted".to_owned(),
    };
    Ok(infallible_pretty_json_response(&response, "{}"))
}
#[iroha_futures::telemetry_future]
pub(crate) async fn handle_post_sorafs_record_por_verdict(
    telemetry: MaybeTelemetry,
    sorafs_node: sorafs_node::NodeHandle,
    sorafs_limits: Arc<SorafsQuotaEnforcer>,
    por_coordinator: Arc<sorafs::PorCoordinator>,
    verdict: AuditVerdictV1,
    authenticated_signer: PublicKey,
    trusted_auditor_keys: Vec<Vec<u8>>,
    auditor_threshold: usize,
    repair_handoff: &dyn sorafs_node::PorRepairHandoff,
) -> Result<impl IntoResponse> {
    verify_authenticated_por_verdict(
        &verdict,
        &authenticated_signer,
        &trusted_auditor_keys,
        auditor_threshold,
    )?;
    if let Err(err) = sorafs_limits.enforce(SorafsAction::PorSubmission, &verdict.provider_id) {
        return Err(quota_limit_error(err));
    }
    let pipeline = por_coordinator.lock_pipeline().await;
    let node_for_worker = sorafs_node.clone();
    let coordinator_for_worker = Arc::clone(&por_coordinator);
    let verdict_for_worker = verdict.clone();
    let (node_result, projection_result) = crate::panic_recovery::join_recoverable(
        crate::panic_recovery::spawn_blocking_recoverable(move || {
        // The owned pipeline guard stays with the non-cancellable physical
        // worker, including its in-place projection update.
        let _pipeline = pipeline;
        match node_for_worker.record_por_verdict_with_authority_update(
            &verdict_for_worker,
            &trusted_auditor_keys,
            auditor_threshold,
        ) {
            Ok((outcome, update)) => (
                Ok(outcome),
                coordinator_for_worker.apply_authoritative_update(update),
            ),
            Err(error) => {
                if error.disposition().invalidates_projection() {
                    coordinator_for_worker.invalidate_authoritative_projection();
                }
                (Err(error.into_tracker_error()), Ok(()))
            }
        }
    }),
    )
    .await
    .map_err(|error| {
        por_coordinator.invalidate_authoritative_projection();
        Error::Query(iroha_data_model::ValidationFail::InternalError(format!(
            "PoR verdict persistence worker failed: {error}"
        )))
    })?;
    projection_result.map_err(por_coordinator_error)?;
    let outcome = node_result.map_err(por_tracker_error)?;
    debug_assert_eq!(
        outcome.repair_task_id.is_some(),
        verdict.outcome == sorafs_manifest::por::AuditOutcomeV1::Failed
    );
    observe_sorafs_metering(&telemetry, &sorafs_node);
    if let Err(error) = sorafs_node.reconcile_next_por_repair_handoff(repair_handoff) {
        iroha_logger::warn!(
            ?error,
            challenge_id = %hex::encode(verdict.challenge_id),
            "PoR verdict committed with a pending durable repair handoff"
        );
    }
    iroha_logger::info!(
        provider_id = %hex::encode(verdict.provider_id),
        challenge_id = %hex::encode(verdict.challenge_id),
        outcome = ?verdict.outcome,
        decided_at = verdict.decided_at,
        "recorded SoraFS PoR verdict"
    );
    let response = RecordPorVerdictResponseDto {
        status: "accepted".to_owned(),
    };
    Ok(infallible_pretty_json_response(&response, "{}"))
}
pub fn handle_get_sorafs_por_status(
    coordinator: Arc<sorafs::PorCoordinator>,
    query: PorStatusQueryDto,
) -> Result<PorStatusPageV1, Error> {
    let manifest = match query.manifest.as_ref() {
        Some(hex) => Some(parse_hex_array::<32>(hex, "manifest")?),
        None => None,
    };
    let provider = match query.provider.as_ref() {
        Some(hex) => Some(parse_hex_array::<32>(hex, "provider")?),
        None => None,
    };
    let outcome =
        match query.status.as_ref() {
            Some(label) => Some(PorChallengeOutcome::parse(label).map_err(|err| {
                conversion_error(format!("invalid `status` value `{label}`: {err}"))
            })?),
            None => None,
        };
    let cursor =
        PorStatusPageCursor::from_opaque(query.cursor.as_deref()).map_err(por_coordinator_error)?;
    let filter = PorStatusFilter {
        manifest,
        provider,
        epoch: query.epoch,
        status: outcome,
    };
    let limits =
        PorStatusPageLimits::new(query.limit, query.max_bytes).map_err(por_coordinator_error)?;
    coordinator
        .query_status_page(&filter, limits, cursor)
        .map_err(por_coordinator_error)
}
pub fn handle_get_sorafs_por_export(
    coordinator: Arc<sorafs::PorCoordinator>,
    query: PorExportQueryDto,
) -> Result<PorStatusExportPageV1, Error> {
    let range = match (query.start_epoch, query.end_epoch) {
        (Some(start), Some(end)) => Some((start, end)),
        (None, None) => None,
        _ => {
            return Err(conversion_error(
                "`start_epoch` and `end_epoch` must be supplied together".to_owned(),
            ));
        }
    };
    let limits =
        PorStatusPageLimits::new(query.limit, query.max_bytes).map_err(por_coordinator_error)?;
    let cursor =
        PorStatusPageCursor::from_opaque(query.cursor.as_deref()).map_err(por_coordinator_error)?;
    coordinator
        .export_status_page(range, limits, cursor)
        .map_err(por_coordinator_error)
}
pub fn handle_get_sorafs_por_report(
    coordinator: Arc<sorafs::PorCoordinator>,
    cycle: PorReportIsoWeek,
) -> Result<PorWeeklyReportV1, Error> {
    coordinator
        .weekly_report(cycle)
        .map_err(por_coordinator_error)
}
}
pub(crate) fn parse_hex_array<const N: usize>(value: &str, field: &str) -> Result<[u8; N], Error> {
    let trimmed = value.trim_start_matches("0x");
    let bytes = hex::decode(trimmed).map_err(|err| {
        conversion_error(format!(
            "invalid hex in `{field}` (expected {N} bytes): {err}"
        ))
    })?;
    let len = bytes.len();
    bytes
        .try_into()
        .map_err(|_| conversion_error(format!("`{field}` must be {N} bytes (got {len})")))
}
#[cfg(feature = "app_api")]
fn observe_sorafs_metering(telemetry: &MaybeTelemetry, sorafs_node: &sorafs_node::NodeHandle) {
    let usage = sorafs_node.capacity_usage();
    let provider_id = match usage.provider_id {
        Some(id) => id,
        None => return,
    };
    let provider_hex = hex::encode(provider_id);
    let snapshot = sorafs_node.metering_snapshot();
    let scheduler = sorafs_node.schedulers();
    let storage_snapshot = scheduler.telemetry_snapshot();
    let fee_projection =
        sorafs_node::metering::FeeProjection::from_snapshot(provider_id, &snapshot);
    telemetry.with_metrics(|tel| {
        tel.record_sorafs_metering(
            &provider_hex,
            snapshot.declared_gib,
            snapshot.effective_gib,
            snapshot.utilised_gib,
            snapshot.outstanding_total_gib,
            snapshot.outstanding_orders,
            snapshot.accumulated_gib_hours,
            snapshot.orders_issued,
            snapshot.orders_completed,
            snapshot.orders_failed,
            snapshot.uptime_bps,
            snapshot.por_success_bps,
        );
        if let Some(projection) = &fee_projection {
            tel.record_sorafs_fee_projection(&provider_hex, &projection.fee);
        }
        tel.record_sorafs_storage(
            &provider_hex,
            storage_snapshot.bytes_used,
            storage_snapshot.bytes_capacity,
            storage_snapshot.provider_ingest_inflight as u64,
            storage_snapshot.fetch_inflight as u64,
            storage_snapshot.fetch_bytes_per_sec,
            storage_snapshot.por_inflight as u64,
            storage_snapshot.por_samples_success,
            storage_snapshot.por_samples_failed,
        );
        for status in sorafs_node.por_ingestion_overview() {
            let manifest_hex = hex::encode(status.manifest_digest);
            let entry_provider_hex = hex::encode(status.provider_id);
            tel.record_sorafs_por_ingestion_backlog(
                &entry_provider_hex,
                &manifest_hex,
                status.pending_challenges,
            );
            tel.record_sorafs_por_ingestion_failures(
                &entry_provider_hex,
                &manifest_hex,
                status.failures_total,
            );
        }
    });
}
fn capacity_declaration_validation_error(err: CapacityDeclarationValidationError) -> Error {
    sorafs_pin_validation_error(
        "sorafs_capacity_declaration_payload_invalid",
        format!("capacity declaration validation failed: {err}"),
    )
}
const fn canonical_padded_base64_len(maximum_decoded_bytes: usize) -> usize {
    maximum_decoded_bytes.div_ceil(3) * 4
}
pub(crate) const POR_PROOF_SUBMISSION_MAX_HTTP_BODY_BYTES_V1: usize =
    canonical_padded_base64_len(POR_PROOF_MAX_CANONICAL_BYTES_V1) + b"{\"proof_b64\":\"\"}".len();
pub(crate) const POR_VERDICT_SUBMISSION_MAX_HTTP_BODY_BYTES_V1: usize =
    canonical_padded_base64_len(AUDIT_VERDICT_MAX_CANONICAL_BYTES_V1)
        + b"{\"verdict_b64\":\"\"}".len();
fn decode_bounded_por_base64(
    payload_b64: &str,
    kind: &str,
    maximum_decoded_bytes: usize,
) -> Result<Vec<u8>, Error> {
    let maximum_encoded_bytes = maximum_decoded_bytes
        .checked_add(2)
        .and_then(|value| value.checked_div(3))
        .and_then(|value| value.checked_mul(4))
        .ok_or_else(|| conversion_error(format!("{kind} payload size limit overflow")))?;
    if payload_b64.len() > maximum_encoded_bytes {
        return Err(conversion_error(format!(
            "{kind}_b64 has {} bytes; maximum canonical base64 length is {maximum_encoded_bytes}",
            payload_b64.len()
        )));
    }
    let bytes = base64::engine::general_purpose::STANDARD
        .decode(payload_b64.as_bytes())
        .map_err(|err| conversion_error(format!("invalid base64 in {kind}_b64: {err}")))?;
    if bytes.len() > maximum_decoded_bytes {
        return Err(conversion_error(format!(
            "{kind} payload has {} decoded bytes; maximum is {maximum_decoded_bytes}",
            bytes.len()
        )));
    }
    if base64::engine::general_purpose::STANDARD.encode(&bytes) != payload_b64 {
        return Err(conversion_error(format!(
            "{kind}_b64 is not canonical padded base64"
        )));
    }
    Ok(bytes)
}
pub(crate) fn decode_por_proof_payload(payload_b64: &str) -> Result<PorProofV1, Error> {
    let bytes = decode_bounded_por_base64(payload_b64, "proof", POR_PROOF_MAX_CANONICAL_BYTES_V1)?;
    decode_por_proof_v1(&bytes)
        .map_err(|err| conversion_error(format!("invalid proof payload: {err}")))
}
pub(crate) fn decode_por_verdict_payload(payload_b64: &str) -> Result<AuditVerdictV1, Error> {
    let bytes =
        decode_bounded_por_base64(payload_b64, "verdict", AUDIT_VERDICT_MAX_CANONICAL_BYTES_V1)?;
    decode_audit_verdict_v1(&bytes)
        .map_err(|err| conversion_error(format!("invalid verdict payload: {err}")))
}
app_api_items! {
fn por_submission_forbidden(code: &'static str, message: impl Into<String>) -> Error {
    Error::AppForbidden {
        code,
        message: message.into(),
    }
}
fn authenticated_ed25519_payload<'a>(
    signer: &'a PublicKey,
    role: &'static str,
) -> Result<&'a [u8], Error> {
    let (algorithm, payload) = signer.try_to_bytes().map_err(|error| {
        por_submission_forbidden(
            "sorafs_por_request_signer_invalid",
            format!("invalid authenticated {role} signer: {error}"),
        )
    })?;
    if algorithm != Algorithm::Ed25519 {
        return Err(por_submission_forbidden(
            "sorafs_por_request_signer_algorithm",
            format!("authenticated {role} signer must use Ed25519"),
        ));
    }
    Ok(payload)
}
fn verify_authenticated_por_proof(
    proof: &PorProofV1,
    authenticated_signer: &PublicKey,
    admitted_provider_key: &[u8],
) -> Result<(), Error> {
    proof
        .validate()
        .map_err(|error| conversion_error(format!("invalid authenticated PoR proof: {error}")))?;
    proof.verify_signature().map_err(|error| {
        por_submission_forbidden(
            "sorafs_por_proof_signature_invalid",
            format!("PoR provider signature verification failed: {error}"),
        )
    })?;
    let request_key = authenticated_ed25519_payload(authenticated_signer, "provider")?;
    if request_key != proof.signature.public_key.as_slice() {
        return Err(por_submission_forbidden(
            "sorafs_por_proof_request_signer_mismatch",
            "authenticated request signer does not match the PoR proof signer",
        ));
    }
    if admitted_provider_key != proof.signature.public_key.as_slice() {
        return Err(por_submission_forbidden(
            "sorafs_por_proof_provider_key_mismatch",
            "PoR proof signer does not match the provider's admitted advert key",
        ));
    }
    Ok(())
}
fn verify_authenticated_por_verdict(
    verdict: &AuditVerdictV1,
    authenticated_signer: &PublicKey,
    trusted_auditor_keys: &[Vec<u8>],
    auditor_threshold: usize,
) -> Result<(), Error> {
    verdict
        .validate()
        .map_err(|error| conversion_error(format!("invalid authenticated PoR verdict: {error}")))?;
    verdict
        .verify_signatures_with_policy(trusted_auditor_keys, auditor_threshold)
        .map_err(|error| {
            por_submission_forbidden(
                "sorafs_por_verdict_signature_invalid",
                format!("PoR auditor signature policy failed: {error}"),
            )
        })?;
    let request_key = authenticated_ed25519_payload(authenticated_signer, "auditor")?;
    if !verdict.has_signer(request_key) {
        return Err(por_submission_forbidden(
            "sorafs_por_verdict_request_signer_mismatch",
            "authenticated request signer is not an auditor signer on the verdict",
        ));
    }
    Ok(())
}
}
fn por_tracker_error(err: sorafs_node::PorTrackerError) -> Error {
    use iroha_data_model::query::error::QueryExecutionFail;
    use sorafs_node::PorTrackerError::*;
    match err {
        UnknownChallenge => Error::Query(iroha_data_model::ValidationFail::QueryFailed(
            QueryExecutionFail::NotFound,
        )),
        other => conversion_error(other.to_string()),
    }
}
fn por_coordinator_error(err: PorCoordinatorError) -> Error {
    use iroha_data_model::query::error::QueryExecutionFail;
    match err {
        PorCoordinatorError::UnknownChallenge { .. } => Error::Query(
            iroha_data_model::ValidationFail::QueryFailed(QueryExecutionFail::NotFound),
        ),
        internal @ (PorCoordinatorError::AuthoritativeProjectionUnavailable
        | PorCoordinatorError::InvalidAuthoritativeProjection(_)
        | PorCoordinatorError::RetentionExhausted { .. }
        | PorCoordinatorError::StatusGenerationExhausted
        | PorCoordinatorError::StatusIndexCorrupt { .. }
        | PorCoordinatorError::StatusPageEncoding(_)
        | PorCoordinatorError::StatusPageByteOverflow
        | PorCoordinatorError::CanonicalVerdictEncoding(_)
        | PorCoordinatorError::RollbackConflict { .. }
        | PorCoordinatorError::IsoWeekComputation
        | PorCoordinatorError::PersistenceFaultLatched { .. }
        | PorCoordinatorError::Persistence(_)) => Error::Query(
            iroha_data_model::ValidationFail::InternalError(internal.to_string()),
        ),
        other => conversion_error(other.to_string()),
    }
}
const SORAFS_PIN_ALIAS_SEGMENT_MAX_BYTES: usize = 128;
const SORAFS_PIN_ALIAS_PROOF_MAX_BYTES: usize = 1024 * 1024;
app_api_items! {
fn validate_single_signed_instruction<'a, T: 'static>(
    network_id: &NetworkId,
    transaction: &'a SignedTransaction,
    network_code: &'static str,
    signature_code: &'static str,
    executable_code: &'static str,
    instruction_count_code: &'static str,
    instruction_type_code: &'static str,
    route_description: &str,
    instruction_name: &str,
) -> Result<&'a T> {
    if transaction.network_id() != Some(network_id) {
        return Err(sorafs_pin_validation_error(
            network_code,
            format!("signed transaction network does not match this Torii for {route_description}"),
        ));
    }
    transaction.verify_signature().map_err(|error| {
        sorafs_pin_validation_error(
            signature_code,
            format!(
                "{route_description} signed transaction signature verification failed: {error}"
            ),
        )
    })?;
    let Executable::Instructions(instructions) = transaction.instructions() else {
        return Err(sorafs_pin_validation_error(
            executable_code,
            format!("{route_description} accepts exactly one {instruction_name} instruction"),
        ));
    };
    let [instruction] = instructions.as_ref() else {
        return Err(sorafs_pin_validation_error(
            instruction_count_code,
            format!("{route_description} accepts exactly one {instruction_name} instruction"),
        ));
    };
    instruction.as_any().downcast_ref::<T>().ok_or_else(|| {
        sorafs_pin_validation_error(
            instruction_type_code,
            format!("{route_description} accepts only {instruction_name}"),
        )
    })
}
fn validate_sorafs_pin_register_transaction<'a>(
    network_id: &NetworkId,
    transaction: &'a SignedTransaction,
) -> Result<&'a iroha_data_model::isi::sorafs::RegisterPinManifest> {
    let register =
        validate_single_signed_instruction::<iroha_data_model::isi::sorafs::RegisterPinManifest>(
            network_id,
            transaction,
            "sorafs_pin_transaction_network_mismatch",
            "sorafs_pin_transaction_signature_invalid",
            "sorafs_pin_transaction_executable_invalid",
            "sorafs_pin_transaction_instruction_count_invalid",
            "sorafs_pin_transaction_instruction_invalid",
            "pin registration",
            "RegisterPinManifest",
        )?;
    if let Some(alias) = register.alias.as_ref() {
        validate_sorafs_pin_alias_binding(alias)?;
    }
    if register
        .successor_of
        .as_ref()
        .is_some_and(|digest| digest.as_bytes().iter().all(|byte| *byte == 0))
    {
        return Err(sorafs_pin_validation_error(
            "sorafs_pin_successor_digest_invalid",
            "RegisterPinManifest.successor_of must be a non-zero digest",
        ));
    }
    Ok(register)
}
fn decode_sorafs_pin_manifest_bytes(
    manifest_bytes: &[u8],
    constraints: &ManifestPinPolicyConstraints,
) -> Result<(ManifestV1, [u8; 32])> {
    if manifest_bytes.is_empty()
        || manifest_bytes.len() > sorafs_manifest::MAX_MANIFEST_ENCODED_BYTES
    {
        return Err(sorafs_pin_validation_error(
            "sorafs_pin_manifest_payload_size_invalid",
            format!(
                "RegisterPinManifest.manifest_payload must contain 1..={} bytes",
                sorafs_manifest::MAX_MANIFEST_ENCODED_BYTES
            ),
        ));
    }
    let manifest =
        sorafs_manifest::decode_manifest_v1_canonical(manifest_bytes).map_err(|err| {
            sorafs_pin_validation_error(
                "sorafs_pin_manifest_payload_decode_failed",
                format!(
                    "invalid canonical Norito ManifestV1 in \
                     RegisterPinManifest.manifest_payload: {err}"
                ),
            )
        })?;
    validate_manifest(&manifest, constraints).map_err(|err| {
        sorafs_pin_manifest_validation_error("sorafs_pin_manifest_payload_invalid", err)
    })?;
    let digest = manifest.digest().map_err(|err| {
        sorafs_pin_validation_error(
            "sorafs_pin_manifest_payload_digest_failed",
            format!("failed to digest manifest_payload: {err}"),
        )
    })?;
    Ok((manifest, *digest.as_bytes()))
}
fn validate_sorafs_pin_alias_segment(value: &str, field: &str) -> Result<()> {
    let bytes = value.as_bytes();
    if bytes.is_empty()
        || bytes.len() > SORAFS_PIN_ALIAS_SEGMENT_MAX_BYTES
        || !bytes.iter().all(|byte| {
            byte.is_ascii_lowercase()
                || byte.is_ascii_digit()
                || matches!(*byte, b'.' | b'-' | b'_')
        })
    {
        return Err(sorafs_pin_validation_error(
            "sorafs_pin_alias_segment_invalid",
            format!(
                "{field} must contain 1..={SORAFS_PIN_ALIAS_SEGMENT_MAX_BYTES} lowercase ASCII \
                 letters, digits, '.', '-', or '_'"
            ),
        ));
    }
    Ok(())
}
fn validate_sorafs_pin_alias_binding(
    alias: &iroha_data_model::sorafs::pin_registry::ManifestAliasBinding,
) -> Result<()> {
    validate_sorafs_pin_alias_segment(&alias.namespace, "alias.namespace")?;
    validate_sorafs_pin_alias_segment(&alias.name, "alias.name")?;
    if alias.proof.is_empty() || alias.proof.len() > SORAFS_PIN_ALIAS_PROOF_MAX_BYTES {
        return Err(sorafs_pin_validation_error(
            "sorafs_pin_alias_proof_size_invalid",
            format!("alias.proof must contain 1..={SORAFS_PIN_ALIAS_PROOF_MAX_BYTES} bytes"),
        ));
    }
    Ok(())
}
}
#[cfg(test)]
fn convert_manifest_policy(
    policy: &ManifestPinPolicy,
) -> iroha_data_model::sorafs::pin_registry::PinPolicy {
    use iroha_data_model::sorafs::pin_registry::StorageClass as DmStorageClass;
    let storage_class = match policy.storage_class {
        ManifestStorageClass::Hot => DmStorageClass::Hot,
        ManifestStorageClass::Warm => DmStorageClass::Warm,
        ManifestStorageClass::Cold => DmStorageClass::Cold,
    };
    iroha_data_model::sorafs::pin_registry::PinPolicy {
        min_replicas: policy.min_replicas,
        storage_class,
        retention_epoch: policy.retention_epoch,
    }
}
#[cfg(feature = "app_api")]
pub fn parse_report_iso_week(label: &str) -> Result<PorReportIsoWeek, Error> {
    let (year_part, week_part) = label
        .split_once("-W")
        .ok_or_else(|| conversion_error("ISO week must be formatted as YYYY-Www".to_string()))?;
    let year: u16 = year_part
        .parse()
        .map_err(|err| conversion_error(format!("invalid ISO week year `{year_part}`: {err}")))?;
    let week: u8 = week_part
        .parse()
        .map_err(|err| conversion_error(format!("invalid ISO week number `{week_part}`: {err}")))?;
    let cycle = PorReportIsoWeek { year, week };
    cycle
        .validate()
        .map_err(|err| conversion_error(format!("invalid ISO week `{label}`: {err}")))?;
    Ok(cycle)
}
fn sorafs_pin_manifest_validation_error(code: &'static str, err: ManifestValidationError) -> Error {
    sorafs_pin_validation_error(code, format!("manifest validation failed: {err}"))
}
fn sorafs_pin_validation_error(code: &'static str, message: impl Into<String>) -> Error {
    Error::AppQueryValidation {
        code,
        message: message.into(),
    }
}
#[cfg(feature = "app_api")]
fn contract_not_found_error(code: &'static str, message: impl Into<String>) -> Error {
    Error::AppNotFound {
        code,
        message: message.into(),
    }
}
fn capacity_limit_error() -> Error {
    Error::Query(iroha_data_model::ValidationFail::QueryFailed(
        iroha_data_model::query::error::QueryExecutionFail::CapacityLimit,
    ))
}
fn quota_limit_error(err: QuotaExceeded) -> Error {
    let _ = err;
    capacity_limit_error()
}
