    routing_test! { async transaction_signature_limit_rejects_and_records_metrics
        let (state, queue, telemetry) = test_state_components([]);
        #[cfg(feature = "telemetry")]
        let before = telemetry.metrics().await.torii_signature_limit_total.get();
        // Build a multisig transaction with more signatures than the default cap (16).
        let signers: Vec<_> = (0_u8..17)
            .map(|offset| {
                checked_capacity_keypair(
                    0x80 + offset,
                    "derive capacity signature-limit fixture signer key",
                )
            })
            .collect();
        let members = signers
            .iter()
            .map(|kp| dm::MultisigMember::new(kp.public_key().clone(), 1).expect("member is valid"))
            .collect::<Vec<_>>();
        let policy = dm::MultisigPolicy::new(1, members).expect("policy");
        let authority = dm::AccountId::new_multisig(policy);
        let tx = dm::TransactionBuilder::new(
            *state.network_id_ref(),
            authority.into(),
            iroha_data_model::transaction::FeePaymentIntent::authority(Vec::new(), None),
        )
        .with_instructions([dm::Log::new(dm::Level::INFO, "too many signatures".into())])
        .sign_multisig(signers.iter().map(iroha_crypto::KeyPair::private_key));
        let result = handle_transaction_with_metrics(
            Arc::clone(&queue),
            Arc::clone(&state),
            tx,
            telemetry.clone(),
            iroha_torii_shared::route_catalog::pipeline::TRANSACTION.path(),
        )
        .await;
        assert!(
            matches!(
                result,
                Err(Error::AcceptTransaction(
                    AcceptTransactionFail::TransactionLimit(_)
                ))
            ),
            "expected signature-limit rejection, got {result:?}"
        );
        #[cfg(feature = "telemetry")]
        {
            let after = telemetry.metrics().await.torii_signature_limit_total.get();
            assert_eq!(
                after,
                before + 1,
                "signature-limit counter should increment on rejection"
            );
        }
    }
    #[tokio::test]
    #[cfg(feature = "app_api")]
