    routing_test! { sync generic_query_and_explorer_visibility_require_every_committed_route_leg
        use iroha_data_model::block::{
            BlockExecutionContextBundle, ExternalExecutionContext, ExternalExecutionRouteLeg,
            ExternalExecutionRouteRole,
        };

        let instruction: dm::InstructionBox =
            dm::Log::new(dm::Level::INFO, "visible".to_owned()).into();
        let (state, _) = build_state_with_single_transaction(vec![instruction]);
        let transaction = committed_transactions_snapshot(state.as_ref())
            .expect("committed transaction snapshot")
            .into_iter()
            .next()
            .expect("test state contains one committed transaction");
        let height = NonZeroUsize::new(state.committed_height()).expect("committed height");
        let mut block = state
            .block_by_height(height)
            .expect("funded canonical history read")
            .expect("committed block remains available")
            .as_ref()
            .clone();
        let (entrypoint_hash, _) = block
            .external_signed_transaction_at(0)
            .expect("external signed transaction");
        let visible_dataspace = DataSpaceId::new(7);
        let hidden_dataspace = DataSpaceId::new(8);
        let coordinator_lane = LaneId::new(7);
        let participant_lane = LaneId::new(8);
        let visibility = DataspaceReadVisibility::new(
            BTreeSet::from([visible_dataspace]),
            false,
        );

        block.set_execution_context(None);
        assert!(!visibility.allows_external_entrypoint(&block, 0));
        assert!(DataspaceReadVisibility::all_for_tests().allows_external_entrypoint(&block, 0));

        block.set_execution_context(Some(BlockExecutionContextBundle::new(vec![
            ExternalExecutionContext::new(entrypoint_hash, coordinator_lane, visible_dataspace),
        ])));
        assert!(visibility.allows_external_entrypoint(&block, 0));
        assert!(committed_transaction_is_visible_in_block(
            &visibility,
            &transaction,
            &block,
        ));
        assert_eq!(
            crate::explorer_history::HistoryBlockRow::from_block(&block, |index| {
                visibility.allows_external_entrypoint(&block, index)
            })
            .transactions_total,
            1,
        );

        let mixed_context = ExternalExecutionContext::with_routing_plan(
            entrypoint_hash,
            coordinator_lane,
            visible_dataspace,
            Hash::new(b"mixed visibility route plan"),
            vec![
                ExternalExecutionRouteLeg::new(
                    coordinator_lane,
                    visible_dataspace,
                    ExternalExecutionRouteRole::Coordinator,
                ),
                ExternalExecutionRouteLeg::new(
                    participant_lane,
                    hidden_dataspace,
                    ExternalExecutionRouteRole::Participant,
                ),
            ],
        );
        block.set_execution_context(Some(BlockExecutionContextBundle::new(vec![mixed_context])));
        assert!(!visibility.allows_external_entrypoint(&block, 0));
        assert!(!committed_transaction_is_visible_in_block(
            &visibility,
            &transaction,
            &block,
        ));
        assert_eq!(
            crate::explorer_history::HistoryBlockRow::from_block(&block, |index| {
                visibility.allows_external_entrypoint(&block, index)
            })
            .transactions_total,
            0,
        );
    }

    routing_test! { sync native_history_rejects_mixed_execution_routes
        use iroha_core::sumeragi::test_chain::{CertifiedTestChain, TestChainConfig};
        use iroha_data_model::block::{BlockExecutionContextBundle, ExternalExecutionContext, ExternalExecutionRouteLeg, ExternalExecutionRouteRole};
        let (authority, key) = checked_explorer_lookup_account(0x20, "mixed route authority");
        let world = World::with([], [dm::Account::new(authority.clone()).build(&authority)], []);
        let mut chain = CertifiedTestChain::start(TestChainConfig::new(world, 1)).unwrap();
        let transaction = dm::TransactionBuilder::new(chain.network_id(), authority, iroha_data_model::transaction::FeePaymentIntent::authority(Vec::new(), None))
            .with_instructions([dm::Log::new(dm::Level::INFO, "mixed".to_owned())]).sign(key.private_key());
        let entrypoint_hash = transaction.hash_as_entrypoint();
        let mut proposal = chain.proposal(None, vec![transaction]);
        proposal.set_execution_context(Some(BlockExecutionContextBundle::new(vec![ExternalExecutionContext::with_routing_plan(
            entrypoint_hash, LaneId::new(7), DataSpaceId::new(7), Hash::new(b"mixed route"),
            vec![ExternalExecutionRouteLeg::new(LaneId::new(7), DataSpaceId::new(7), ExternalExecutionRouteRole::Coordinator),
                 ExternalExecutionRouteLeg::new(LaneId::new(8), DataSpaceId::new(8), ExternalExecutionRouteRole::Participant)],
        )])));
        assert!(chain.begin_proposal(proposal, Default::default()).is_err());
        assert_eq!(chain.height(), 1, "unsupported mixed route never enters committed history");
    }

    routing_test! { sync explorer_stream_serializes_one_item_at_a_time
        let visibility = DataspaceReadVisibility::all_for_tests();
        let first: dm::InstructionBox = dm::Log::new(dm::Level::INFO, "first".to_owned()).into();
        let second: dm::InstructionBox = dm::Log::new(dm::Level::INFO, "second".to_owned()).into();
        let third: dm::InstructionBox = dm::Log::new(dm::Level::INFO, "third".to_owned()).into();
        let (state, _) = build_state_with_transactions(vec![vec![first, second], vec![third]]);
        let mut blocks = explorer_pending_for_state(&state);
        assert!(blocks.next_payload(ExplorerStreamKind::Blocks, &visibility).unwrap().is_some());
        assert!(blocks.next_payload(ExplorerStreamKind::Blocks, &visibility).unwrap().is_none());
        let mut transactions = explorer_pending_for_state(&state);
        assert!(
            transactions
                .next_payload(ExplorerStreamKind::Transactions, &visibility).unwrap()
                .is_some()
        );
        assert_eq!(transactions.entrypoint_index, 1);
        assert!(
            transactions
                .next_payload(ExplorerStreamKind::Transactions, &visibility).unwrap()
                .is_some()
        );
        assert_eq!(transactions.entrypoint_index, 2);
        assert!(
            transactions
                .next_payload(ExplorerStreamKind::Transactions, &visibility).unwrap()
                .is_none()
        );
        let mut instructions = explorer_pending_for_state(&state);
        assert!(
            instructions
                .next_payload(ExplorerStreamKind::Instructions, &visibility).unwrap()
                .is_some()
        );
        assert_eq!(instructions.entrypoint_index, 1);
        assert_eq!(instructions.instruction_index, 1);
        assert!(instructions.current_entrypoint.is_some());
        assert!(
            instructions
                .next_payload(ExplorerStreamKind::Instructions, &visibility).unwrap()
                .is_some()
        );
        assert_eq!(instructions.entrypoint_index, 1);
        assert_eq!(instructions.instruction_index, 2);
        assert!(
            instructions
                .next_payload(ExplorerStreamKind::Instructions, &visibility).unwrap()
                .is_some()
        );
        assert_eq!(instructions.entrypoint_index, 2);
        assert_eq!(instructions.instruction_index, 1);
        assert!(
            instructions
                .next_payload(ExplorerStreamKind::Instructions, &visibility).unwrap()
                .is_none()
        );
        assert!(instructions.current_entrypoint.is_none());
    }
    fn build_state_with_unindexed_kura_transaction(
        instructions: Vec<dm::InstructionBox>,
    ) -> (Arc<State>, HashOf<TransactionEntrypoint>) {
        let (chain, mut hashes) = build_chain_with_executables_and_route_plans(
            vec![dm::Executable::from(instructions)], None, None,
        );
        let indexed = chain.state();
        let target_hash = hashes.remove(0);
        let stored = indexed
            .block_by_height(NonZeroUsize::new(indexed.committed_height()).unwrap())
            .expect("original native history read")
            .expect("actual executed successor remains in Kura");
        assert!(
            crate::canonical_history::signed_calls(stored.as_ref())
                .expect("original certified execution outputs")
                .any(|(hash, _, _)| hash == target_hash),
            "the lookup target really exists in the authenticated Kura body"
        );
        // A fresh, unapplied State has no transaction index even though its Kura
        // contains the real signed genesis and certified successor.
        let state = Arc::new(State::new_with_chain_and_network_id_for_testing(
            World::default(),
            Arc::clone(chain.kura()),
            LiveQueryStore::start_test(),
            indexed.chain_id_ref().clone(),
            *indexed.network_id_ref(),
        ));
        assert_eq!(state.committed_height(), 0);
        (state, target_hash)
    }
    routing_test! { sync explorer_transaction_history_cursor_and_has_more_ignore_hidden_entrypoints
        let visible_dataspace = DataSpaceId::new(7);
        let hidden_dataspace = DataSpaceId::new(8);
        let instruction_batches = ["visible-first", "hidden-middle", "visible-last", "hidden-tail"]
            .into_iter()
            .map(|message| vec![dm::Log::new(dm::Level::INFO, message.to_owned()).into()])
            .collect();
        let (state, hashes) = build_state_with_routed_transactions(
            instruction_batches,
            vec![
                visible_dataspace,
                hidden_dataspace,
                visible_dataspace,
                hidden_dataspace,
            ],
            None,
        );
        let visibility =
            DataspaceReadVisibility::new(BTreeSet::from([visible_dataspace]), false);
        let filters = ExplorerTransactionFilters {
            authority: None,
            status: None,
            block: None,
            asset_id: None,
        };
        let owner = crate::history_producer::HistoryProducerOwner::for_test();
        let collection = crate::explorer::ExplorerHistoryCollection::Transactions;
        let first_query = crate::explorer::ExplorerCursorQuery {
            cursor: None,
            limit: 1,
        };
        let (items, pagination) = owner.scope(|| collect_transaction_summaries(
            state.as_ref(),
            &visibility,
            &filters,
            &first_query,
            collection,
        ))
        .expect("first visible transaction page");
        assert_eq!(items.len(), 1);
        assert_eq!(items[0].entrypoint_hash.to_string(), hashes[0].to_string());
        assert!(pagination.has_more);
        let cursor = pagination.next_cursor.expect("visible continuation");
        let decoded = owner.scope(|| crate::explorer::decode_explorer_history_cursor(
            &cursor,
            collection,
            transaction_history_filter_digest(collection, &filters).expect("admitted transaction filter digest"),
            visibility.visible_route_set_digest(),
        ))
        .expect("decode transaction history cursor");
        assert_eq!(decoded.position.entrypoint_hash, Some(hashes[2]));

        let (items, pagination) = owner.scope(|| collect_transaction_summaries(
            state.as_ref(),
            &visibility,
            &filters,
            &crate::explorer::ExplorerCursorQuery {
                cursor: Some(cursor),
                limit: 1,
            },
            collection,
        ))
        .expect("second visible transaction page");
        assert_eq!(items.len(), 1);
        assert_eq!(items[0].entrypoint_hash.to_string(), hashes[2].to_string());
        assert!(!pagination.has_more);
        assert!(pagination.next_cursor.is_none());
    }
    routing_test! { sync explorer_history_resume_hash_is_stable_across_hidden_insertion
        let visible_dataspace = DataSpaceId::new(7);
        let hidden_dataspace = DataSpaceId::new(8);
        // Inserting an input must preserve its peers' signing authorities and the
        // authenticated genesis network, including the unused hidden lane.
        let route_plans = vec![
            vec![(LaneId::new(1), visible_dataspace)],
            vec![(LaneId::new(2), hidden_dataspace)],
            vec![(LaneId::new(3), visible_dataspace)],
        ];
        let executable = |message: &str| {
            dm::Executable::from(vec![dm::InstructionBox::from(dm::Log::new(
                dm::Level::INFO, message.to_owned(),
            ))])
        };
        let (baseline_chain, baseline_hashes) = build_chain_with_selected_authorities(
            vec![executable("visible-first"), executable("visible-next")],
            Some(route_plans.clone()),
            Some(vec![1_710_000_000_000, 1_710_000_000_002]),
            vec![0, 2],
        );
        let (hidden_chain, hidden_hashes) = build_chain_with_selected_authorities(
            vec![
                executable("visible-first"),
                executable("hidden"),
                executable("visible-next"),
            ],
            Some(route_plans),
            Some(vec![
                1_710_000_000_000,
                1_710_000_000_001,
                1_710_000_000_002,
            ]),
            vec![0, 1, 2],
        );
        assert_eq!(baseline_chain.network_id(), hidden_chain.network_id());
        let baseline = Arc::clone(baseline_chain.state());
        let with_hidden = Arc::clone(hidden_chain.state());
        assert_eq!(baseline_hashes[0], hidden_hashes[0]);
        assert_eq!(baseline_hashes[1], hidden_hashes[2]);
        let visibility =
            DataspaceReadVisibility::new(BTreeSet::from([visible_dataspace]), false);
        let filters = ExplorerTransactionFilters {
            authority: None,
            status: None,
            block: None,
            asset_id: None,
        };
        let owner = crate::history_producer::HistoryProducerOwner::for_test();
        let collection = crate::explorer::ExplorerHistoryCollection::Transactions;
        let query = crate::explorer::ExplorerCursorQuery {
            cursor: None,
            limit: 1,
        };
        let (_, baseline_page) = owner.scope(|| collect_transaction_summaries(
            baseline.as_ref(),
            &visibility,
            &filters,
            &query,
            collection,
        ))
        .expect("baseline transaction page");
        let (_, hidden_page) = owner.scope(|| collect_transaction_summaries(
            with_hidden.as_ref(),
            &visibility,
            &filters,
            &query,
            collection,
        ))
        .expect("transaction page with hidden insertion");
        let filter_digest = owner.scope(|| transaction_history_filter_digest(collection, &filters))
            .expect("admitted transaction filter digest");
        let baseline_cursor = owner.scope(|| crate::explorer::decode_explorer_history_cursor(
            baseline_page.next_cursor.as_deref().expect("baseline cursor"),
            collection,
            filter_digest,
            visibility.visible_route_set_digest(),
        ))
        .expect("decode baseline cursor");
        let hidden_cursor = owner.scope(|| crate::explorer::decode_explorer_history_cursor(
            hidden_page.next_cursor.as_deref().expect("hidden-insertion cursor"),
            collection,
            filter_digest,
            visibility.visible_route_set_digest(),
        ))
        .expect("decode hidden-insertion cursor");
        assert_eq!(baseline_cursor.position, hidden_cursor.position);
        assert_eq!(
            hidden_cursor.position.entrypoint_hash,
            Some(hidden_hashes[2])
        );

        let height = NonZeroUsize::new(with_hidden.committed_height()).expect("committed height");
        let block = with_hidden
            .block_by_height(height)
            .expect("funded canonical history read")
            .expect("committed routed block");
        let hidden_probe = resolve_explorer_history_entrypoint(
            block.as_ref(),
            &visibility,
            crate::explorer::ExplorerHistoryPosition::transaction(
                u64::try_from(height.get()).expect("height fits u64"),
                hidden_hashes[1],
            ),
        )
        .expect_err("hidden resume hash must be rejected");
        let absent_probe = resolve_explorer_history_entrypoint(
            block.as_ref(),
            &visibility,
            crate::explorer::ExplorerHistoryPosition::transaction(
                u64::try_from(height.get()).expect("height fits u64"),
                HashOf::from_untyped_unchecked(Hash::new(b"absent explorer entrypoint")),
            ),
        )
        .expect_err("absent resume hash must be rejected");
        let duplicate_probe = resolve_unique_explorer_history_entrypoint_index(
            [Some(hidden_hashes[1]), Some(hidden_hashes[1])],
            hidden_hashes[1],
        )
        .expect_err("duplicate resume hash must be rejected");
        assert_eq!(hidden_probe.to_string(), absent_probe.to_string());
        assert_eq!(hidden_probe.to_string(), duplicate_probe.to_string());
    }
