    routing_test! { async explorer_instructions_endpoint_account_filter_includes_mint_and_burn
        use axum::{Router, routing::get};
        use tower::ServiceExt;
        let (alice, _) =
            checked_explorer_lookup_account(0x24, "derive explorer instructions alice fixture key");
        let (bob, _) =
            checked_explorer_lookup_account(0x25, "derive explorer instructions bob fixture key");
        let def: dm::AssetDefinitionId =
            test_asset_definition_id_from_hex("550e8400e29b41d4a7164466554400bb");
        let alice_asset = dm::AssetId::new(def.clone(), alice.clone());
        let bob_asset = dm::AssetId::new(def, bob.clone());
        let instructions = vec![
            dm::Mint::asset_quantity(10_u32, alice_asset.clone()).into(),
            dm::Burn::asset_quantity(1_u32, alice_asset).into(),
            dm::Mint::asset_quantity(10_u32, bob_asset.clone()).into(),
            dm::Burn::asset_quantity(1_u32, bob_asset).into(),
        ];
        let (state, tx_hash) = build_state_with_single_transaction(instructions);
        let app = Router::new().route(
            ENDPOINT_EXPLORER_INSTRUCTIONS,
            get({
                let state = state.clone();
                move |crate::NoritoQuery(query): crate::NoritoQuery<
                    ExplorerInstructionsEndpointQuery,
                >| {
                    let state = state.clone();
                    async move {
                        let account = query.account.map(|raw| {
                            dm::AccountId::parse_encoded(&raw)
                                .expect("test query account should parse")
                        });
                        let pagination = crate::explorer::ExplorerCursorQuery {
                            cursor: query.cursor,
                            limit: query.limit.unwrap_or(20),
                        };
                        handle_v1_explorer_instructions(
                            state,
                            MaybeTelemetry::disabled(),
                            DataspaceReadVisibility::all_for_tests(),
                            pagination,
                            ExplorerInstructionQuery {
                                account,
                                authority: None,
                                transaction_hash: None,
                                status: None,
                                block: None,
                                kind: None,
                                asset_id: None,
                            },
                        )
                        .await
                    }
                }
            }),
        );
        let req = http::Request::builder()
            .method("GET")
            .uri(format!(
                "{ENDPOINT_EXPLORER_INSTRUCTIONS}?account={}&limit=10",
                urlencoding::encode(&alice.to_string())
            ))
            .body(axum::body::Body::empty())
            .unwrap();
        let resp = app.oneshot(req).await.unwrap();
        assert_eq!(resp.status(), http::StatusCode::OK);
        let body = resp.into_body().collect().await.unwrap().to_bytes();
        let payload: norito::json::Value = norito::json::from_slice(&body).unwrap();
        let items = payload["items"].as_array().expect("items array");
        assert_eq!(items.len(), 2);
        let expected_hash = tx_hash.to_string();
        for item in items {
            assert_eq!(
                item["transaction_hash"].as_str(),
                Some(expected_hash.as_str())
            );
        }
        let mut indexes: Vec<u64> = items
            .iter()
            .filter_map(|item| item["index"].as_u64())
            .collect();
        indexes.sort_unstable();
        assert_eq!(indexes, vec![0, 1]);
        let mut kinds: Vec<String> = items
            .iter()
            .filter_map(|item| item["kind"].as_str().map(ToOwned::to_owned))
            .collect();
        kinds.sort();
        assert_eq!(kinds, vec!["Burn".to_owned(), "Mint".to_owned()]);
    }
