    fn xor_asset_definition_id() -> AssetDefinitionId {
        iroha_data_model::parameter::system::SumeragiNposParameters::default()
            .xor_asset_definition_id
    }
    fn payout_contract_address(state: &State, user: &AccountId) -> ContractAddress {
        ContractAddress::derive(state.network_id_ref(), user, 0, DataSpaceId::UNIVERSAL)
            .expect("derive original network payout address")
    }
    fn pool_contract_address(state: &State, user: &AccountId) -> ContractAddress {
        ContractAddress::derive(state.network_id_ref(), user, 1, DataSpaceId::UNIVERSAL)
            .expect("derive original network pool address")
    }
    fn unit_return_code() -> Vec<u8> {
        use ivm::{
            encoding::wide,
            instruction::wide::{arithmetic, control, memory},
        };
        [
            wide::encode_store(memory::STORE64, 12, 0, 0),
            wide::encode_ri(arithmetic::ADDI, 10, 12, 0),
            wide::encode_ri(arithmetic::ADDI, 11, 0, 1),
            wide::encode_rr(control::JALR, 0, 1, 0),
        ]
        .into_iter()
        .flat_map(u32::to_le_bytes)
        .collect()
    }
    fn reward_and_reference_accounts() -> Vec<AccountId> {
        [7, 10, 11, 12, 13, 14]
            .into_iter()
            .map(|seed| {
                account(
                    seed,
                    "derive reward custody or independent reference provider",
                )
                .0
            })
            .collect()
    }
    fn payout_contract_artifact() -> (
        Vec<u8>,
        iroha_data_model::smart_contract::manifest::ContractManifest,
    ) {
        let metadata = ivm::ProgramMetadata {
            version_major: 1,
            version_minor: 1,
            mode: 0,
            vector_length: 0,
            max_cycles: 4,
            abi_version: 1,
        };
        let entrypoint = iroha_data_model::smart_contract::manifest::EntrypointDescriptor {
            name: "autonomous_validation_fee_tick".to_owned(),
            kind: iroha_data_model::smart_contract::manifest::EntryPointKind::Kotoage,
            params: Vec::new(),
            argument_schema: None,
            return_type: Some("()".to_owned()),
            return_schema: Some(iroha_data_model::smart_contract::entrypoint::EntrypointValueTypeV1 {
                nodes: vec![iroha_data_model::smart_contract::entrypoint::EntrypointValueTypeNodeV1::Unit],
            }),
            authorization: iroha_data_model::smart_contract::manifest::EntrypointAuthorizationV1::Permission("Payout".parse().unwrap()),
            read_keys: Vec::new(),
            write_keys: Vec::new(),
            access_hints_complete: None,
            access_hints_skipped: Vec::new(),
            triggers: vec![TriggerDescriptor {
                id: "validation_fee_payout_tick"
                    .parse()
                    .expect("payout trigger id"),
                repeats: Repeats::Indefinitely,
                filter: EventFilterBox::Time(TimeEventFilter(ExecutionTime::PreCommit)),
                authority: None,
                metadata: Metadata::default(),
                callback: TriggerCallback {
                    namespace: None,
                    entrypoint: "autonomous_validation_fee_tick".to_owned(),
                },
            }],
        };
        let interface = ivm::EmbeddedContractInterfaceV1 {
            events: Vec::new(),
            enum_types: Vec::new(),
            permissions: vec![iroha_data_model::smart_contract::manifest::ContractPermissionDescriptorV1 {name:"Payout".parse().unwrap(),scope:iroha_data_model::smart_contract::manifest::ContractPermissionScopeV1::Instance}],
            callables: vec![ivm::call::EmbeddedCallableV1 {
                entry_pc: 0,
                frame_bytes: 0,
                arguments: ivm::call::CallSchemaV1::empty(),
                results: ivm::call::CallSchemaV1::unit(),
            }],
            seiyaku_name: "ValidationFeePayout".to_owned(),
            compiler_fingerprint: "validation-fee-torii-ingress-test".to_owned(),
            abi_hash: ivm::syscalls::compute_abi_hash(ivm::SyscallPolicy::AbiV1),
            features_bitmap: 0,
            access_set_hints: None,
            kotoba: Vec::new(),
            entrypoints: vec![ivm::EmbeddedEntrypointDescriptor {
                name: entrypoint.name.clone(),
                kind: entrypoint.kind,
                params: entrypoint.params.clone(),
                argument_schema: entrypoint.argument_schema.clone(),
                return_type: entrypoint.return_type.clone(),
                return_schema: entrypoint.return_schema.clone(),
                authorization: entrypoint.authorization.clone(),
                read_keys: entrypoint.read_keys.clone(),
                write_keys: entrypoint.write_keys.clone(),
                access_hints_complete: entrypoint.access_hints_complete,
                access_hints_skipped: entrypoint.access_hints_skipped.clone(),
                triggers: entrypoint.triggers.clone(),
                entry_pc: 0,
            }],
            error_messages: Vec::new(),
            error_types: Vec::new(),
            states: Vec::new(),
        };
        let mut artifact = metadata.encode();
        artifact.extend_from_slice(&interface.encode_section());
        artifact.extend_from_slice(&unit_return_code());
        let verified =
            ivm::verify_contract_artifact(&artifact).expect("valid payout contract artifact");
        (artifact, verified.manifest)
    }
    fn pool_contract_artifact() -> (
        Vec<u8>,
        iroha_data_model::smart_contract::manifest::ContractManifest,
    ) {
        let metadata = ivm::ProgramMetadata {
            version_major: 1,
            version_minor: 1,
            mode: 0,
            vector_length: 0,
            max_cycles: 4,
            abi_version: 1,
        };
        let entrypoint = iroha_data_model::smart_contract::manifest::EntrypointDescriptor {
            name: "swap_exact_in_quote_public".to_owned(),
            kind: iroha_data_model::smart_contract::manifest::EntryPointKind::Kotoage,
            params: Vec::new(),
            argument_schema: None,
            return_type: Some("()".to_owned()),
            return_schema: Some(iroha_data_model::smart_contract::entrypoint::EntrypointValueTypeV1 {
                nodes: vec![iroha_data_model::smart_contract::entrypoint::EntrypointValueTypeNodeV1::Unit],
            }),
            authorization: iroha_data_model::smart_contract::manifest::EntrypointAuthorizationV1::Permission("SwapQuotePublic".parse().unwrap()),
            read_keys: Vec::new(),
            write_keys: Vec::new(),
            access_hints_complete: None,
            access_hints_skipped: Vec::new(),
            triggers: Vec::new(),
        };
        let interface = ivm::EmbeddedContractInterfaceV1 {
            events: Vec::new(),
            enum_types: Vec::new(),
            permissions: vec![iroha_data_model::smart_contract::manifest::ContractPermissionDescriptorV1 {name:"SwapQuotePublic".parse().unwrap(),scope:iroha_data_model::smart_contract::manifest::ContractPermissionScopeV1::Instance}],
            callables: vec![ivm::call::EmbeddedCallableV1 {
                entry_pc: 0,
                frame_bytes: 0,
                arguments: ivm::call::CallSchemaV1::empty(),
                results: ivm::call::CallSchemaV1::unit(),
            }],
            seiyaku_name: "ValidationFeePool".to_owned(),
            compiler_fingerprint: "validation-fee-pool-torii-ingress-test".to_owned(),
            abi_hash: ivm::syscalls::compute_abi_hash(ivm::SyscallPolicy::AbiV1),
            features_bitmap: 0,
            access_set_hints: None,
            kotoba: Vec::new(),
            entrypoints: vec![ivm::EmbeddedEntrypointDescriptor {
                name: entrypoint.name.clone(),
                kind: entrypoint.kind,
                params: entrypoint.params.clone(),
                argument_schema: entrypoint.argument_schema.clone(),
                return_type: entrypoint.return_type.clone(),
                return_schema: entrypoint.return_schema.clone(),
                authorization: entrypoint.authorization.clone(),
                read_keys: entrypoint.read_keys.clone(),
                write_keys: entrypoint.write_keys.clone(),
                access_hints_complete: entrypoint.access_hints_complete,
                access_hints_skipped: entrypoint.access_hints_skipped.clone(),
                triggers: entrypoint.triggers.clone(),
                entry_pc: 0,
            }],
            error_messages: Vec::new(),
            error_types: Vec::new(),
            states: Vec::new(),
        };
        let mut artifact = metadata.encode();
        artifact.extend_from_slice(&interface.encode_section());
        artifact.extend_from_slice(&unit_return_code());
        let verified =
            ivm::verify_contract_artifact(&artifact).expect("valid pool contract artifact");
        (artifact, verified.manifest)
    }
