#[cfg(all(test, feature = "app_api"))]
mod sponsored_onboarding_dto_tests {
    use super::{
        AccountFaucetPrepareRequestDto, AccountFaucetRequestDto,
        AccountOnboardingPlanReceiptDto, AccountOnboardingPlanRequestDto,
        AccountOnboardingPrepareRequestDto, PreparedOperationBindingV1,
        account_onboarding_receipt_signature_is_valid, canonical_faucet_claim_account,
        canonical_onboarding_account_id, checked_routing_fixture_keypair,
        onboarding_disposition_transition_allowed, onboarding_frames_are_ordered_subset,
    };
    use iroha_crypto::{Algorithm, Hash, Signature};
    use iroha_data_model::{
        account::{AccountId, MultisigMember, MultisigPolicy},
        alias_setup::{AliasFramedInstructionV1, AliasPlanDispositionV1},
        transaction::FeePaymentIntent,
    };
    routing_test! { sync plan_request_is_secret_free_and_rejects_legacy_fields
        let request = AccountOnboardingPlanRequestDto {
            version: AccountOnboardingPlanRequestDto::VERSION,
            alias: "merchant@banka.paynet".to_owned(),
            account_id: iroha_test_samples::ALICE_ID.to_string(),
            permissions: Vec::new(),
        };
        let encoded = norito::json::to_json(&request).expect("serialize onboarding plan request");
        for forbidden in ["private_key", "token", "uaid", "identity_commitment"] {
            assert!(!encoded.contains(forbidden));
        }
        for forbidden in ["private_key", "token", "uaid", "public_key_hex"] {
            let encoded = format!(
                r#"{{"version":1,"alias":"merchant@banka.paynet","account_id":"{}","{forbidden}":"forbidden"}}"#,
                iroha_test_samples::ALICE_ID.to_string()
            );
            assert!(
                norito::json::from_str::<AccountOnboardingPlanRequestDto>(&encoded).is_err(),
                "legacy or secret-bearing field must be rejected: {forbidden}"
            );
        }
    }
    routing_test! { sync onboarding_and_faucet_v1_json_reject_omitted_fields
        let request = AccountOnboardingPlanRequestDto {
            version: AccountOnboardingPlanRequestDto::VERSION,
            alias: "merchant@banka.paynet".to_owned(),
            account_id: iroha_test_samples::ALICE_ID.to_string(),
            permissions: Vec::new(),
        };
        let mut request_json =
            norito::json::to_value(&request).expect("encode exact onboarding request");
        assert_eq!(
            norito::json::from_value::<AccountOnboardingPlanRequestDto>(request_json.clone())
                .expect("round-trip exact onboarding request"),
            request
        );
        assert!(
            request_json
                .as_object_mut()
                .expect("onboarding request object")
                .remove("permissions")
                .is_some()
        );
        assert!(
            norito::json::from_value::<AccountOnboardingPlanRequestDto>(request_json).is_err(),
            "an omitted V1 permissions vector must not default to empty"
        );

        let claim = AccountFaucetRequestDto {
            account_id: iroha_test_samples::ALICE_ID.to_string(),
            pow_anchor_height: 7,
            pow_nonce_hex: "00".repeat(8),
        };
        let claim_json = norito::json::to_value(&claim).expect("encode exact faucet claim");
        assert_eq!(
            norito::json::from_value::<AccountFaucetRequestDto>(claim_json.clone())
                .expect("round-trip exact faucet claim"),
            claim
        );
        for field in ["pow_anchor_height", "pow_nonce_hex"] {
            let mut missing = claim_json.clone();
            assert!(
                missing
                    .as_object_mut()
                    .expect("faucet claim object")
                    .remove(field)
                    .is_some()
            );
            assert!(
                norito::json::from_value::<AccountFaucetRequestDto>(missing).is_err(),
                "an omitted V1 faucet field must fail: {field}"
            );

            let mut null = claim_json.clone();
            null.as_object_mut()
                .expect("faucet claim object")
                .insert(field.to_owned(), norito::json::Value::Null);
            assert!(
                norito::json::from_value::<AccountFaucetRequestDto>(null).is_err(),
                "a null V1 faucet field must fail: {field}"
            );
        }
    }
    routing_test! { sync onboarding_receipt_v1_json_rejects_omitted_slots
        let fixture: norito::json::Value = norito::json::from_slice(include_bytes!(concat!(
            env!("CARGO_MANIFEST_DIR"),
            "/../../fixtures/norito_rpc/alias_setup_v1/alias_setup_v1.json"
        )))
        .expect("decode shared alias-setup fixture");
        let receipt_json = fixture["account_onboarding_receipt_vector"]["receipt_json"].clone();
        let receipt: AccountOnboardingPlanReceiptDto =
            norito::json::from_value(receipt_json.clone()).expect("decode exact receipt fixture");
        assert_eq!(
            norito::json::to_value(&receipt).expect("re-encode exact receipt fixture"),
            receipt_json
        );
        for path in [
            &["body", "request", "permissions"][..],
            &["body", "owner_auto_renew_instruction"][..],
            &["body", "acquisition", "pricing_class_hint"][..],
            &["body", "resource", "quote"][..],
            &["body", "resource", "instruction_index"][..],
        ] {
            let mut missing = receipt_json.clone();
            let mut object = missing.as_object_mut().expect("receipt object");
            for segment in &path[..path.len() - 1] {
                object = object
                    .get_mut(*segment)
                    .and_then(norito::json::Value::as_object_mut)
                    .expect("nested receipt object");
            }
            let field = path[path.len() - 1];
            assert!(object.remove(field).is_some(), "fixture contains {field}");
            assert!(
                norito::json::from_value::<AccountOnboardingPlanReceiptDto>(missing).is_err(),
                "an omitted V1 receipt field must fail: {}",
                path.join(".")
            );
        }
    }
    routing_test! { sync prepared_account_requests_require_an_explicit_fee_selection
        let fixture: norito::json::Value = norito::json::from_slice(include_bytes!(concat!(
            env!("CARGO_MANIFEST_DIR"),
            "/../../fixtures/norito_rpc/alias_setup_v1/alias_setup_v1.json"
        )))
        .expect("decode shared alias-setup fixture");
        let receipt: AccountOnboardingPlanReceiptDto = norito::json::from_value(
            fixture["account_onboarding_receipt_vector"]["receipt_json"].clone(),
        )
        .expect("decode exact receipt fixture");
        let binding = PreparedOperationBindingV1 {
            schema: PreparedOperationBindingV1::SCHEMA.to_owned(),
            semantic_hash_hex: "11".repeat(32),

            kind: "onboarding".to_owned(),

            request_id: "22".repeat(32),
            execution_expires_at_unix_ms: u64::MAX,
        };
        let fee_payment = FeePaymentIntent::authority(Vec::new(), None);
        let onboarding = AccountOnboardingPrepareRequestDto {
            schema: AccountOnboardingPrepareRequestDto::SCHEMA.to_owned(),
            binding: binding.clone(),
            receipt,
            fee_payment: fee_payment.clone(),
        };
        let mut onboarding_json =
            norito::json::to_value(&onboarding).expect("encode onboarding prepare request");
        assert!(
            onboarding_json
                .as_object_mut()
                .expect("onboarding prepare object")
                .remove("fee_payment")
                .is_some()
        );
        assert!(
            norito::json::from_value::<AccountOnboardingPrepareRequestDto>(onboarding_json)
                .is_err(),
            "onboarding prepare must not default a missing fee selection"
        );

        let faucet = AccountFaucetPrepareRequestDto {
            schema: AccountFaucetPrepareRequestDto::SCHEMA.to_owned(),
            binding,
            claim: AccountFaucetRequestDto {
                account_id: iroha_test_samples::ALICE_ID.to_string(),
                pow_anchor_height: 7,
                pow_nonce_hex: "00".repeat(8),
            },
            fee_payment,
        };
        let mut faucet_json =
            norito::json::to_value(&faucet).expect("encode faucet prepare request");
        assert!(
            faucet_json
                .as_object_mut()
                .expect("faucet prepare object")
                .remove("fee_payment")
                .is_some()
        );
        assert!(
            norito::json::from_value::<AccountFaucetPrepareRequestDto>(faucet_json).is_err(),
            "faucet prepare must not default a missing fee selection"
        );
    }
    routing_test! { sync onboarding_and_faucet_reject_padded_account_ids
        let canonical = iroha_test_samples::ALICE_ID.to_string();
        for padded in [format!(" {canonical}"), format!("{canonical} ")] {
            assert!(
                canonical_onboarding_account_id(&padded).is_err(),
                "onboarding accepted padded account_id {padded:?}"
            );
            let claim = AccountFaucetRequestDto {
                account_id: padded.clone(),
                pow_anchor_height: 7,
                pow_nonce_hex: "00".repeat(8),
            };
            assert!(
                canonical_faucet_claim_account(&claim).is_err(),
                "faucet accepted padded account_id {padded:?}"
            );
        }
        assert_eq!(
            canonical_onboarding_account_id(&canonical)
                .expect("canonical onboarding account literal"),
            iroha_test_samples::ALICE_ID.clone()
        );
        assert_eq!(
            canonical_faucet_claim_account(&AccountFaucetRequestDto {
                account_id: canonical,
                pow_anchor_height: 7,
                pow_nonce_hex: "00".repeat(8),
            })
            .expect("canonical faucet account literal"),
            iroha_test_samples::ALICE_ID.clone()
        );

        for claim in [
            AccountFaucetRequestDto {
                account_id: iroha_test_samples::ALICE_ID.to_string(),
                pow_anchor_height: 0,
                pow_nonce_hex: "00".repeat(8),
            },
            AccountFaucetRequestDto {
                account_id: iroha_test_samples::ALICE_ID.to_string(),
                pow_anchor_height: 7,
                pow_nonce_hex: String::new(),
            },
            AccountFaucetRequestDto {
                account_id: iroha_test_samples::ALICE_ID.to_string(),
                pow_anchor_height: 7,
                pow_nonce_hex: "AA".to_owned(),
            },
            AccountFaucetRequestDto {
                account_id: iroha_test_samples::ALICE_ID.to_string(),
                pow_anchor_height: 7,
                pow_nonce_hex: "00".repeat(33),
            },
        ] {
            assert!(
                canonical_faucet_claim_account(&claim).is_err(),
                "noncanonical V1 faucet proof must fail: {claim:?}"
            );
        }
    }
    routing_test! { sync receipt_disposition_transitions_only_allow_idempotent_progress
        use AliasPlanDispositionV1::{Conflict, Create, NoOp, Repair};
        for live in [Create, Repair, NoOp] {
            assert!(onboarding_disposition_transition_allowed(Create, live));
        }
        assert!(onboarding_disposition_transition_allowed(Repair, Repair));
        assert!(onboarding_disposition_transition_allowed(Repair, NoOp));
        assert!(onboarding_disposition_transition_allowed(NoOp, NoOp));
        for (planned, live) in [
            (NoOp, Repair),
            (NoOp, Create),
            (Repair, Create),
            (Conflict, NoOp),
            (Create, Conflict),
        ] {
            assert!(!onboarding_disposition_transition_allowed(planned, live));
        }
    }
    routing_test! { sync live_receipt_frames_may_only_remove_already_completed_work
        let frame = |wire_id: &str, byte| AliasFramedInstructionV1 {
            wire_id: wire_id.to_owned(),
            framed_payload: vec![byte],
        };
        let ensure = frame("iroha.alias.ensure", 1);
        let grant_a = frame("iroha.grant", 2);
        let grant_b = frame("iroha.grant", 3);
        let planned = vec![ensure.clone(), grant_a, grant_b.clone()];
        assert!(onboarding_frames_are_ordered_subset(
            &[ensure.clone(), grant_b.clone()],
            &planned,
        ));
        assert!(onboarding_frames_are_ordered_subset(&[], &planned));
        assert!(!onboarding_frames_are_ordered_subset(
            &[ensure, frame("nexus::EnrollFeeSponsorBeneficiary", 4)],
            &planned,
        ));
        assert!(!onboarding_frames_are_ordered_subset(
            &[grant_b, frame("iroha.alias.ensure", 1)],
            &planned,
        ));
    }
    routing_test! { sync receipt_signature_rejects_multisig_authority_without_panicking
        let signer = checked_routing_fixture_keypair(
            0xa9,
            Algorithm::Ed25519,
            "derive onboarding receipt multisig fixture key",
        );
        let plan_hash = Hash::new(b"onboarding receipt multisig rejection");
        let signature = Signature::try_new(signer.private_key(), plan_hash.as_ref())
            .expect("sign onboarding receipt fixture");
        let member =
            MultisigMember::new(signer.public_key().clone(), 1).expect("valid multisig member");
        let policy = MultisigPolicy::new(1, vec![member]).expect("valid multisig policy");
        let authority = AccountId::new_multisig(policy);
        assert!(!account_onboarding_receipt_signature_is_valid(
            &authority, &signature, &plan_hash,
        ));
    }
}
