app_api_items! {
fn validator_record_to_json(record: &PublicLaneValidatorRecord) -> (String, Value) {
    let mut map = Map::new();
    let canonical_validator = record.validator.to_string();
    let validator_literal = crate::account_literal::display_literal(&record.validator);
    let stake_literal = crate::account_literal::display_literal(&record.stake_account);
    map.insert("lane_id".into(), Value::from(u64::from(record.lane_id)));
    map.insert("validator".into(), Value::from(validator_literal));
    map.insert("peer_id".into(), Value::from(record.peer_id.to_string()));
    map.insert("stake_account".into(), Value::from(stake_literal));
    map.insert(
        "total_stake".into(),
        Value::from(record.total_stake.to_string()),
    );
    map.insert(
        "self_stake".into(),
        Value::from(record.self_stake.to_string()),
    );
    map.insert("status".into(), validator_status_to_json(&record.status));
    map.insert(
        "activation_height".into(),
        Value::from(record.activation_height),
    );
    map.insert(
        "election_exit_height".into(),
        record.election_exit_height.map(Value::from).unwrap_or(Value::Null),
    );
    map.insert(
        "deactivation_height".into(),
        record
            .deactivation_height
            .map(Value::from)
            .unwrap_or(Value::Null),
    );
    map.insert("metadata".into(), metadata_to_json(&record.metadata));
    map.insert("authority_source".into(), Value::from("staking"));
    (canonical_validator, Value::Object(map))
}
fn manifest_validator_to_json(
    lane_id: LaneId,
    binding: &iroha_core::governance::manifest::ManifestValidatorBinding,
) -> (String, Value) {
    let mut map = Map::new();
    let canonical_validator = binding.validator.to_string();
    let validator_literal = crate::account_literal::display_literal(&binding.validator);
    map.insert("lane_id".into(), Value::from(u64::from(lane_id)));
    map.insert("validator".into(), Value::from(validator_literal.clone()));
    map.insert("peer_id".into(), Value::from(binding.peer_id.to_string()));
    map.insert("stake_account".into(), Value::from(validator_literal));
    map.insert("total_stake".into(), Value::from("0"));
    map.insert("self_stake".into(), Value::from("0"));
    map.insert(
        "status".into(),
        validator_status_to_json(&PublicLaneValidatorStatus::Active),
    );
    map.insert("activation_height".into(), Value::Null);
    map.insert("election_exit_height".into(), Value::Null);
    map.insert("deactivation_height".into(), Value::Null);
    map.insert("metadata".into(), metadata_to_json(&Metadata::default()));
    map.insert("authority_source".into(), Value::from("manifest"));
    (canonical_validator, Value::Object(map))
}
fn validator_status_to_json(status: &PublicLaneValidatorStatus) -> Value {
    let mut map = Map::new();
    match status {
        PublicLaneValidatorStatus::PendingActivation(activates_at_height) => {
            map.insert("type".into(), Value::from("PendingActivation"));
            map.insert(
                "activates_at_height".into(),
                Value::from(*activates_at_height),
            );
        }
        PublicLaneValidatorStatus::Active => {
            map.insert("type".into(), Value::from("Active"));
        }
        PublicLaneValidatorStatus::Exiting(releases_at_ms) => {
            map.insert("type".into(), Value::from("Exiting"));
            map.insert("releases_at_ms".into(), Value::from(*releases_at_ms));
        }
        PublicLaneValidatorStatus::Exited => {
            map.insert("type".into(), Value::from("Exited"));
        }
        PublicLaneValidatorStatus::Slashed(slash_id) => {
            map.insert("type".into(), Value::from("Slashed"));
            map.insert("slash_id".into(), Value::from(format!("{slash_id}")));
        }
    }
    Value::Object(map)
}
fn stake_share_to_json(share: &PublicLaneStakeShare) -> (String, Value) {
    let mut map = Map::new();
    let canonical_validator = share.validator.to_string();
    let canonical_staker = share.staker.to_string();
    let validator_literal = crate::account_literal::display_literal(&share.validator);
    let staker_literal = crate::account_literal::display_literal(&share.staker);
    map.insert("lane_id".into(), Value::from(u64::from(share.lane_id)));
    map.insert("validator".into(), Value::from(validator_literal));
    map.insert("staker".into(), Value::from(staker_literal));
    map.insert("bonded".into(), Value::from(share.bonded.to_string()));
    map.insert("metadata".into(), metadata_to_json(&share.metadata));
    let pending: Vec<_> = share
        .pending_unbonds
        .values()
        .map(public_lane_unbonding_to_json)
        .collect();
    map.insert("pending_unbonds".into(), Value::Array(pending));
    (
        format!("{canonical_validator}#{canonical_staker}"),
        Value::Object(map),
    )
}
fn pending_reward_to_json(
    reward: iroha_data_model::nexus::PublicLanePendingReward,
) -> (String, Value) {
    let mut map = Map::new();
    let account_literal = crate::account_literal::display_literal(&reward.account);
    map.insert("lane_id".into(), Value::from(u64::from(reward.lane_id)));
    map.insert("account".into(), Value::from(account_literal));
    map.insert("asset".into(), Value::from(reward.asset.to_string()));
    map.insert("beneficiary_id".into(), Value::from(reward.beneficiary_id.to_string()));
    map.insert("beneficiary_revision".into(), Value::from(reward.beneficiary_revision));
    map.insert("expected_claim_sequence".into(), Value::from(reward.expected_claim_sequence));
    map.insert("lifecycle_seal".into(), Value::from(hex::encode(reward.lifecycle_seal)));
    map.insert("claimable".into(), Value::from(reward.claimable));
    map.insert("amount".into(), Value::from(reward.amount.to_string()));
    (
        reward.asset.to_string(),
        Value::Object(map),
    )
}
fn public_lane_unbonding_to_json(unbonding: &PublicLaneUnbonding) -> Value {
    let mut map = Map::new();
    map.insert(
        "request_id".into(),
        Value::from(hex::encode(unbonding.request_id.as_ref())),
    );
    map.insert("amount".into(), Value::from(unbonding.amount.to_string()));
    map.insert("release_at_ms".into(), Value::from(unbonding.release_at_ms));
    map.insert(
        "slashable_through_height".into(),
        Value::from(unbonding.slashable_through_height),
    );
    map.insert(
        "liability_release_height".into(),
        Value::from(unbonding.liability_release_height),
    );
    Value::Object(map)
}
fn exact_field_filter_candidates<T>(
    expr: Option<&crate::filter::FilterExpr>,
    field_name: &str,
    parse_value: &impl Fn(&Value) -> Option<T>,
) -> Option<BTreeSet<T>>
where
    T: Ord,
{
    use crate::filter::FilterExpr as F;
    match expr? {
        F::And(list) => {
            let mut selected: Option<BTreeSet<T>> = None;
            for nested in list {
                if let Some(candidates) =
                    exact_field_filter_candidates(Some(nested), field_name, parse_value)
                {
                    if let Some(selected) = selected.as_mut() {
                        selected.retain(|id| candidates.contains(id));
                    } else {
                        selected = Some(candidates);
                    }
                }
            }
            selected
        }
        F::Or(list) => {
            let mut union = BTreeSet::new();
            for nested in list {
                let candidates =
                    exact_field_filter_candidates(Some(nested), field_name, parse_value)?;
                union.extend(candidates);
            }
            Some(union)
        }
        F::Eq(field, value) if field.0 == field_name => {
            Some(parse_value(value).into_iter().collect())
        }
        F::In(field, values) if field.0 == field_name => {
            Some(values.iter().filter_map(parse_value).collect())
        }
        _ => None,
    }
}
// ---------------------- NFTs listing ----------------------
fn nft_filter_candidate_ids(expr: Option<&crate::filter::FilterExpr>) -> Option<BTreeSet<NftId>> {
    exact_field_filter_candidates(expr, "id", &|value| value.as_str()?.parse().ok())
}
fn nft_from_key_value(id: &NftId, value: &iroha_data_model::nft::NftValue) -> Nft {
    let details = value.clone().into_inner();
    Nft {
        id: id.clone(),
        content: details.content,
        owned_by: details.owned_by,
    }
}
}
#[cfg(all(test, feature = "app_api"))]
routing_test! { sync nft_filter_candidate_ids_extracts_safe_exact_constraints
    let first: NftId = "ticket$art".parse().unwrap();
    let second: NftId = "receipt$art".parse().unwrap();
    let exact = FilterExpr::Eq(
        FieldPath("id".to_owned()),
        norito::json::Value::from(first.to_string()),
    );
    let candidates = nft_filter_candidate_ids(Some(&exact))
        .expect("NFT id equality should produce direct lookup candidates");
    assert_eq!(candidates, BTreeSet::from([first.clone()]));
    let combined = FilterExpr::And(vec![
        exact.clone(),
        FilterExpr::Exists(FieldPath("metadata.kind".to_owned())),
    ]);
    let candidates =
        nft_filter_candidate_ids(Some(&combined)).expect("AND should preserve safe id candidates");
    assert_eq!(candidates, BTreeSet::from([first]));
    let many = FilterExpr::In(
        FieldPath("id".to_owned()),
        vec![
            norito::json::Value::from("not-an-nft-id"),
            norito::json::Value::from(second.to_string()),
        ],
    );
    let candidates =
        nft_filter_candidate_ids(Some(&many)).expect("NFT id IN should produce candidates");
    assert_eq!(candidates, BTreeSet::from([second]));
    let unsafe_or = FilterExpr::Or(vec![
        exact,
        FilterExpr::Exists(FieldPath("metadata.kind".to_owned())),
    ]);
    assert!(nft_filter_candidate_ids(Some(&unsafe_or)).is_none());
}
