fn name_status_label(status: &NameStatus) -> &'static str {
    match status {
        NameStatus::Active => "active",
        NameStatus::GracePeriod => "grace_period",
        NameStatus::Redemption => "redemption",
        NameStatus::Frozen(_) => "frozen",
        NameStatus::Tombstoned(_) => "tombstoned",
    }
}
fn account_alias_lease_dto_from_record(
    alias: String,
    dataspace: String,
    domain: Option<String>,
    is_primary: bool,
    record: &NameRecordV1,
    auto_renew: Option<&iroha_data_model::alias_setup::AliasAutoRenewStateV1>,
) -> AccountAliasLeaseDto {
    let auto_renew_enabled =
        auto_renew.is_some_and(|state| state.config.is_some() && state.suspended_reason.is_none());
    AccountAliasLeaseDto {
        alias,
        dataspace,
        domain,
        is_primary,
        lease_status: name_status_label(&record.status).to_owned(),
        expires_at_ms: record.expires_at_ms,
        grace_expires_at_ms: record.grace_expires_at_ms,
        redemption_expires_at_ms: record.redemption_expires_at_ms,
        auto_renew_enabled,
        auto_renew_revision: auto_renew.map(|state| state.revision),
        next_retry_at_ms: auto_renew.and_then(|state| state.next_retry_at_ms),
        auto_renew_failure_count: auto_renew.map(|state| state.failure_count),
        auto_renew_suspended_reason: auto_renew.and_then(|state| state.suspended_reason.clone()),
        max_renewal_amount: auto_renew
            .and_then(|state| state.config.as_ref())
            .map(|config| config.max_amount.clone()),
    }
}
fn network_time_ms() -> Result<u64> {
    let now = time::now().now;
    let duration = now
        .duration_since(SystemTime::UNIX_EPOCH)
        .map_err(|err| conversion_error(format!("invalid network time: {err}")))?;
    u64::try_from(duration.as_millis())
        .map_err(|_| conversion_error("network time milliseconds overflow".to_string()))
}
fn default_charge_ms(now_ms: u64, billing: SubscriptionBilling) -> Result<u64> {
    use iroha_primitives::calendar;
    match billing.cadence {
        SubscriptionCadence::MonthlyCalendar(cadence) => {
            let anchor = calendar::monthly_anchor_at_or_before(
                now_ms,
                cadence.anchor_day,
                cadence.anchor_time_ms,
            )
            .map_err(|err| conversion_error(format!("invalid cadence anchor: {err}")))?;
            if anchor == now_ms {
                Ok(now_ms)
            } else {
                calendar::monthly_anchor_after(now_ms, cadence.anchor_day, cadence.anchor_time_ms)
                    .map_err(|err| conversion_error(format!("invalid cadence anchor: {err}")))
            }
        }
        SubscriptionCadence::FixedPeriod(cadence) => {
            if cadence.period_ms == 0 {
                return Err(conversion_error(
                    "billing period must be positive".to_string(),
                ));
            }
            match billing.bill_for {
                SubscriptionBillFor::PreviousPeriod => now_ms
                    .checked_add(cadence.period_ms)
                    .ok_or_else(|| conversion_error("billing period overflow".to_string())),
                SubscriptionBillFor::NextPeriod => Ok(now_ms),
            }
        }
    }
}
fn resolve_charge_ms(billing: SubscriptionBilling, requested: Option<u64>) -> Result<u64> {
    if let Some(value) = requested {
        return Ok(value);
    }
    let now_ms = network_time_ms()?;
    default_charge_ms(now_ms, billing)
}
fn initial_period_for_charge(
    billing: SubscriptionBilling,
    charge_at_ms: u64,
) -> Result<(u64, u64)> {
    use iroha_primitives::calendar;
    match billing.cadence {
        SubscriptionCadence::MonthlyCalendar(cadence) => {
            let direction = match billing.bill_for {
                SubscriptionBillFor::PreviousPeriod => calendar::BillingPeriod::Previous,
                SubscriptionBillFor::NextPeriod => calendar::BillingPeriod::Next,
            };
            let period = calendar::monthly_billing_period(
                charge_at_ms,
                cadence.anchor_day,
                cadence.anchor_time_ms,
                direction,
            )
            .map_err(|err| conversion_error(format!("invalid cadence anchor: {err}")))?;
            Ok((period.start_ms, period.end_ms))
        }
        SubscriptionCadence::FixedPeriod(cadence) => {
            if cadence.period_ms == 0 {
                return Err(conversion_error(
                    "billing period must be positive".to_string(),
                ));
            }
            match billing.bill_for {
                SubscriptionBillFor::PreviousPeriod => {
                    let start = charge_at_ms
                        .checked_sub(cadence.period_ms)
                        .ok_or_else(|| conversion_error("billing period overflow".to_string()))?;
                    Ok((start, charge_at_ms))
                }
                SubscriptionBillFor::NextPeriod => charge_at_ms
                    .checked_add(cadence.period_ms)
                    .map(|end| (charge_at_ms, end))
                    .ok_or_else(|| conversion_error("billing period overflow".to_string())),
            }
        }
    }
}
fn derive_trigger_id(prefix: &str, subscription_id: &NftId) -> Result<TriggerId> {
    let hash = Hash::new(subscription_id.to_string());
    let name = format!("{prefix}{}", hex::encode(hash.as_ref()));
    TriggerId::from_str(&name)
        .map_err(|err| conversion_error(format!("invalid derived trigger id: {err}")))
}
fn resolve_trigger_id(
    prefix: &str,
    subscription_id: &NftId,
    explicit: Option<TriggerId>,
) -> Result<TriggerId> {
    explicit
        .map(Ok)
        .unwrap_or_else(|| derive_trigger_id(prefix, subscription_id))
}
fn subscription_instruction_drafts(
    instructions: impl IntoIterator<Item = InstructionBox>,
) -> Result<Vec<SubscriptionInstructionDraft>> {
    use iroha_data_model::isi::Instruction;
    instructions
        .into_iter()
        .map(|instruction| {
            let type_name = Instruction::id(&*instruction);
            let (wire_id, framed) =
                iroha_data_model::isi::framed_instruction_payload(&instruction).ok_or_else(
                    || {
                        conversion_error(format!(
                            "failed to frame subscription draft instruction `{type_name}`"
                        ))
                    },
                )?;
            Ok(SubscriptionInstructionDraft {
                wire_id: wire_id.to_owned(),
                payload_hex: hex::encode(framed),
            })
        })
        .collect()
}
fn subscription_billing_trigger_operation(existed: bool, included: bool) -> &'static str {
    match (existed, included) {
        (false, false) => "none",
        (false, true) => "register",
        (true, false) => "unregister",
        (true, true) => "replace",
    }
}
fn subscription_action_draft_response(
    authority: AccountId,
    action: &'static str,
    subscription_id: NftId,
    resulting_subscription: SubscriptionState,
    billing_trigger_existed: bool,
    billing_trigger_included: bool,
    effective_charge_ms: Option<u64>,
    cancel_mode: Option<SubscriptionCancelMode>,
    instructions: Vec<InstructionBox>,
) -> Result<JsonBody<SubscriptionActionResponse>> {
    let billing_trigger_id = resulting_subscription.billing_trigger_id.clone();
    let tx_instructions = subscription_instruction_drafts(instructions)?;
    Ok(JsonBody(SubscriptionActionResponse {
        version: SUBSCRIPTION_MUTATION_DRAFT_VERSION_V1,
        authority,
        action: action.to_owned(),
        subscription_id,
        details: SubscriptionActionDraftDetails {
            billing_trigger_id,
            billing_trigger_operation: subscription_billing_trigger_operation(
                billing_trigger_existed,
                billing_trigger_included,
            )
            .to_owned(),
            effective_charge_ms,
            cancel_mode,
            resulting_subscription,
        },
        tx_instructions,
    }))
}
fn ivm_syscall_program(syscall: u32, max_cycles: NonZeroU64) -> IvmBytecode {
    let opcode = u8::try_from(syscall).expect("syscall opcode fits in u8");
    let mut code = Vec::new();
    code.extend_from_slice(
        &ivm::encoding::wide::encode_sys(ivm::instruction::wide::system::SCALL, opcode)
            .to_le_bytes(),
    );
    code.extend_from_slice(&ivm::encoding::wide::encode_halt().to_le_bytes());
    let mut blob = ivm::ProgramMetadata {
        max_cycles: max_cycles.get(),
        ..ivm::ProgramMetadata::default()
    }
    .encode();
    blob.extend_from_slice(&code);
    IvmBytecode::from_compiled(blob)
}
fn build_billing_trigger(
    trigger_id: TriggerId,
    authority: AccountId,
    subscription_id: NftId,
    charge_at_ms: u64,
    max_cycles: NonZeroU64,
) -> Trigger {
    use iroha_data_model::events::time::{ExecutionTime, Schedule, TimeEventFilter};
    let schedule = Schedule {
        start_ms: charge_at_ms,
        period_ms: None,
    };
    let mut metadata = Metadata::default();
    metadata.insert(
        (*SUBSCRIPTION_TRIGGER_REF_KEY).clone(),
        IrohaJson::new(SubscriptionTriggerRef {
            subscription_nft_id: subscription_id,
        }),
    );
    let action = Action::new(
        Executable::Ivm(ivm_syscall_program(
            ivm::syscalls::SYSCALL_SUBSCRIPTION_BILL,
            max_cycles,
        )),
        Repeats::Exactly(1),
        authority,
        TimeEventFilter(ExecutionTime::Schedule(schedule)),
    )
    .expect("trigger action fixture satisfies validation invariants")
    .with_metadata(metadata);
    Trigger::new(trigger_id, action)
}
fn build_usage_trigger(
    trigger_id: TriggerId,
    authority: AccountId,
    max_cycles: NonZeroU64,
) -> Trigger {
    use iroha_data_model::events::execute_trigger::ExecuteTriggerEventFilter;
    let action = Action::new(
        Executable::Ivm(ivm_syscall_program(
            ivm::syscalls::SYSCALL_SUBSCRIPTION_RECORD_USAGE,
            max_cycles,
        )),
        Repeats::Indefinitely,
        authority.clone(),
        ExecuteTriggerEventFilter::new()
            .for_trigger(trigger_id.clone())
            .under_authority(authority),
    )
    .expect("trigger action fixture satisfies validation invariants");
    Trigger::new(trigger_id, action)
}
#[iroha_futures::telemetry_future]
pub async fn handle_post_v1_subscription_plan(
    queue: Arc<Queue>,
    state: Arc<CoreState>,
    NoritoJson(req): NoritoJson<SubscriptionPlanCreateRequest>,
) -> Result<JsonBody<SubscriptionPlanCreateResponse>> {
    let SubscriptionPlanCreateRequest {
        authority,
        plan_id,
        plan,
    } = req;
    if plan.provider != authority {
        return Err(conversion_error(
            "plan provider must match authority".to_string(),
        ));
    }
    let plan_key = (*SUBSCRIPTION_PLAN_KEY).clone();
    let instructions = vec![
        InstructionBox::from(Register::asset_definition(AssetDefinition::numeric(
            plan_id.clone(),
            asset_definition_display_name(&plan_id),
            iroha_data_model::asset::AssetBalancePolicy::Global,
            None,
        ))),
        InstructionBox::from(SetKeyValue::asset_definition(
            plan_id.clone(),
            plan_key,
            IrohaJson::new(plan),
        )),
    ];
    let builder = quote_app_api_transaction_builder(
        new_app_api_transaction_builder_from_state(state.as_ref(), authority.clone())
            .with_instructions(instructions),
        queue.as_ref(),
        state.as_ref(),
        ENDPOINT_SUBSCRIPTION_PLANS_LIST,
    )?;
    let draft = app_api_transaction_draft(&builder);
    Ok(JsonBody(SubscriptionPlanCreateResponse {
        submitted: draft.submitted,
        plan_id,
        transaction_payload_b64: draft.transaction_payload_b64,
        signing_message_b64: draft.signing_message_b64,
    }))
}
